  if (!S.path && o.path && o.path !== "flat") o = Object.assign({}, o, {path: "flat"});
  var P = {G: G, initial: o.initial * (1 - G.share), strat: S, path: null, rg: null, risk: null, first: 0,
    floor: ddFloorSched(o)};
