/* iOS decimal keypad has no minus key, so rates get an explicit sign flip. */
document.addEventListener("click", e => {
  const b = e.target.closest ? e.target.closest(".signflip") : null;
  if (!b) return;
  const el = b.parentNode.querySelector("input");
  if (!el) return;
  const v = parseNum(el.value);
  el.value = String(-v);
  b.classList.toggle("on", -v < 0);
  el.dispatchEvent(new Event("input", {bubbles:true}));
  el.dispatchEvent(new Event("change", {bubbles:true}));
});

/* ---------- the Calculator tab's mode menu ----------
   Basic, Advanced and Stages live behind one tab. The tab shows the open
   mode, and remembers it: the menu is how you switch. With a mouse it opens
   on hover, and clicking the tab returns to the remembered mode. Its layout (dropdown,
   full-width phone sheet, or a sheet rising from the web app's bottom bar)
   is all CSS; the script only places it under the tab on a wide screen. */
const CALC_MODES = {simple:"Basic", single:"Advanced", series:"Stages"};
const CALCBTN = $("tabbtn-calc");
const CALCITEMS = Array.prototype.slice.call(
  document.querySelectorAll("#calcMenu [role=menuitemradio]"));
function calcModeSync(t){
  if (CALC_MODES[t] == null) return;
  $("calcMode").textContent = CALC_MODES[t];
  CALCBTN.setAttribute("aria-controls", "tab-" + t);
  CALCITEMS.forEach(x => x.setAttribute("aria-checked", String(x.getAttribute("data-mode") === t)));
}
function calcMenuPlace(){
  const m = $("calcMenu"), nb = CALCBTN.closest(".navbar");
  const bl = CALCBTN.getBoundingClientRect().left - nb.getBoundingClientRect().left;
  // Line the menu's text up with the tab's, but never past the right edge.
  const max = nb.clientWidth - m.offsetWidth - 10;
  m.style.left = Math.max(10, Math.min(bl - 12, max)) + "px";
}
function calcMenuOpen(focusItem, hover){
  const m = $("calcMenu");
  m.hidden = false;
  $("calcScrim").hidden = !!hover;
  CALCBTN.closest(".navbar").classList.add("menu-open");
  CALCBTN.setAttribute("aria-expanded", "true");
  calcMenuPlace();
  if (focusItem){
    const cur = CALCITEMS.find(x => x.getAttribute("aria-checked") === "true") || CALCITEMS[0];
    cur.focus();
  }
}
function calcMenuClose(refocus){
  const m = $("calcMenu");
  if (m.hidden) return;
  m.hidden = true;
  $("calcScrim").hidden = true;
  CALCBTN.closest(".navbar").classList.remove("menu-open");
  CALCBTN.setAttribute("aria-expanded", "false");
  if (refocus) CALCBTN.focus();
}
CALCITEMS.forEach((it, i) => {
  it.addEventListener("click", e => {
    const t = it.getAttribute("data-mode");
    calcMenuClose(e.detail === 0);
    if (t !== chartMode.tab){
      paneDir = "tab";
      showTab(t);
      pushNav();
    }
  });
  it.addEventListener("keydown", e => {
    let j = -1;
    if (e.key === "ArrowDown") j = (i + 1) % CALCITEMS.length;
    else if (e.key === "ArrowUp") j = (i - 1 + CALCITEMS.length) % CALCITEMS.length;
    else if (e.key === "Home") j = 0;
    else if (e.key === "End") j = CALCITEMS.length - 1;
    else if (e.key === "Escape"){ e.preventDefault(); calcMenuClose(true); return; }
    else if (e.key === "Tab"){ calcMenuClose(false); return; }
    if (j < 0) return;
    e.preventDefault();
    CALCITEMS[j].focus();
  });
});
$("calcScrim").addEventListener("click", () => calcMenuClose(false));
/* With a mouse, the menu opens on hover and the tab itself goes straight to
   the mode you were last on. Touch screens have no hover, so there a tap on
   the tab still opens the menu. A short delay on leaving lets the pointer
   cross from the tab to the menu, and the menu's ::before covers the gap. */
const CALC_HOVER = window.matchMedia ? window.matchMedia("(hover:hover) and (pointer:fine)") : null;
function calcHover(){ return !!(CALC_HOVER && CALC_HOVER.matches); }
let calcHoverTimer = null;
[CALCBTN, $("calcMenu")].forEach(el => {
  el.addEventListener("mouseenter", () => {
    if (!calcHover()) return;
    clearTimeout(calcHoverTimer);
    if ($("calcMenu").hidden) calcMenuOpen(false, true);
  });
  el.addEventListener("mouseleave", () => {
    if (!calcHover()) return;
    clearTimeout(calcHoverTimer);
    calcHoverTimer = setTimeout(() => {
      // keep it open while a keyboard user is inside it
      if (!$("calcMenu").contains(document.activeElement)) calcMenuClose(false);
    }, 220);
  });
});
function calcLastMode(){
  const cur = CALCITEMS.find(x => x.getAttribute("aria-checked") === "true");
  return cur ? cur.getAttribute("data-mode") : "simple";
}
// A press anywhere outside the menu and its tab closes it. pointerdown rather
// than click, so the press that starts a scroll on a phone counts too.
document.addEventListener("pointerdown", e => {
  if ($("calcMenu").hidden || !e.target.closest) return;
  if (e.target.closest("#calcMenu") || e.target.closest("#tabbtn-calc")) return;
  calcMenuClose(false);
}, true);
document.addEventListener("keydown", e => {
  if (e.key === "Escape" && !$("calcMenu").hidden) calcMenuClose(true);
});
window.addEventListener("resize", () => { if (!$("calcMenu").hidden) calcMenuPlace(); });

/* Direction of the next pane swap, consumed by playPaneEnter. Set by whichever
   control initiated the move; defaults back to a plain tab change so a stray
   programmatic showTab can't inherit a stale direction. */
let paneDir = "tab";
const PANE_CLASSES = ["pane-in","pane-in-fwd","pane-in-back","pane-in-cards"];
/* Runs after the [hidden] flags are set, so it animates whatever actually
   ended up visible rather than trying to predict it. Removing the class and
   reading offsetWidth forces a reflow, which is what lets the same animation
   replay on a repeat visit to the same pane. */
function playPaneEnter(){
  const dir = paneDir;
  paneDir = "tab";
  const panes = Array.prototype.filter.call(
    document.querySelectorAll("#main > .stack, #main > aside"), el => !el.hidden);
  panes.forEach(el => {
    const cls = (el.id === "tab-toolpicker") ? "pane-in-cards"
      : (dir === "fwd") ? "pane-in-fwd"
      : (dir === "back") ? "pane-in-back" : "pane-in";
    PANE_CLASSES.forEach(c => el.classList.remove(c));
    void el.offsetWidth;
    el.classList.add(cls);
  });
}

/* The back row is the first grid item in main and spans every column, so it
   sits above the input pane in both layouts. Its label is read off the picker
   card rather than duplicated here, so the two can't drift apart. */
function setToolBack(sub){
  const row = $("toolBack"), onPicker = (sub === "picker");
  row.hidden = onPicker;
  if (onPicker) return;
  const card = document.querySelector('.toolcard[data-pick="' + sub + '"]');
  if (!card) return;
  // The header repeats the card you picked: its icon tile, name (and badge)
  // and one-line description.
  const name = card.querySelector(".toolcard-name"), badge = name && name.querySelector(".beta");
  $("toolCrumb").textContent = toolName(name);
  if (badge) $("toolCrumb").appendChild(badge.cloneNode(true));
  const ic = card.querySelector(".toolcard-icon");
  $("toolHeadIcon").innerHTML = ic ? ic.innerHTML : "";
  const d = card.querySelector(".toolcard-desc");
  $("toolHeadDesc").textContent = d ? d.textContent.trim() : "";
}
$("btnToolBack").addEventListener("click", () => {
  paneDir = "back";
  showTool("picker");
  pushNav();
});

/* Tab and tool moves are pushed as history entries so the phone's back
   gesture steps back through the app instead of leaving it. The state lives
   in the entry object, not the URL, so a share link's hash is untouched. */
let navSuspended = false;
/* Clean paths for the tools that have one (e.g. /incometax), built from a
   single table so the two directions can't drift apart. Tabs/states with no
   entry here (compare views, the picker's own url) just don't rewrite the
   address bar. A share link's hash (#s= or #p=) still wins on load when present,
   since it carries full input state, not just which tab is open. */
const TOOL_PATHS = {
  tax:"incometax", mortgage:"mortgage", budget:"budget", college:"college",
  rentbuy:"rentbuy", drawdown:"drawdown", roth:"roth", debt:"debt",
  backtest:"backtest", healthcare:"healthcare", fire:"fire", bridge:"bridge",
  optimizer:"optimizer"
};
const SUB_BY_PATH = {};
Object.keys(TOOL_PATHS).forEach(sub => { SUB_BY_PATH[TOOL_PATHS[sub]] = sub; });
/* Tab ids are "single" and "series" inside the code, but the address shows
   the names on the tabs. The old /single and /series addresses still open
   the right tab, so bookmarks and links shared before the rename keep working. */
const TAB_PATHS = {single:"advanced", series:"stages", about:"about", guide:"guide"};
const TAB_BY_PATH = {advanced:"single", stages:"series", about:"about",
                     single:"single", series:"series", guide:"guide"};
function pathForRoute(t, s){
  if (t === "simple") return "/";
  if (TAB_PATHS[t]) return "/" + TAB_PATHS[t];
  if (t === "tools") return "/" + (TOOL_PATHS[s] || "tools");
  return null;
}
/* Search landing pages that open an existing tool under their own address:
   /rmd is the Roth tool, /72t the Bridge. The address stays as it came in
   (see the boot's canonical swap) and the page shows its own article. */
const PATH_ALIAS = {rmd:"roth", "72t":"bridge"};
function pathSeg(path){ return path.replace(/^\/+|\/+$/g, "").replace(/\.html$/, ""); }
function routeFromPath(path){
  const seg = pathSeg(path);
  if (!seg) return null;
  if (PATH_ALIAS[seg]) return {t:"tools", s:PATH_ALIAS[seg]};
  if (TAB_BY_PATH[seg]) return {t:TAB_BY_PATH[seg]};
  if (seg === "tools") return {t:"tools", s:"picker"};
  if (SUB_BY_PATH[seg]) return {t:"tools", s:SUB_BY_PATH[seg]};
  return null;
}
function pushNav(){
  if (navSuspended) return;
  try {
    const path = pathForRoute(chartMode.tab, toolSub);
    if (path) history.pushState({t:chartMode.tab, s:toolSub}, "", path);
    else history.pushState({t:chartMode.tab, s:toolSub}, "");
  } catch(e){}
}
window.addEventListener("popstate", e => {
  const st = e.state;
  if (!st || !st.t) return;
  navSuspended = true;
  if (st.t === "compare"){
    if (chartMode.tab === "compare"){ navSuspended = false; return; }
    paneDir = "tab";
    showCompare();
    navSuspended = false;
    return;
  }
  if (st.t === "dd-compare"){
    if (chartMode.tab === "dd-compare"){ navSuspended = false; return; }
    paneDir = "tab";
    showDDCompare();
    navSuspended = false;
    return;
  }
  if (chartMode.tab === "compare") chartMode.tab = cmpPrevTab;
  if (chartMode.tab === "dd-compare") chartMode.tab = ddCmpPrevTab;
  paneDir = (st.t === "tools" && st.s === "picker") ? "back" : "tab";
  // The guide used to be a tool, so an older entry can still say so.
  if (st.t === "tools" && st.s === "guide") showTab("guide");
  else if (st.t === "tools"){ toolSub = st.s || "picker"; showTab("tools"); }
  else showTab(st.t);
  navSuspended = false;
});

/* Tools is a container tab: picking it reveals a second row for choosing which
   tool, so more can be added later without crowding the main nav. */
let toolSub = "picker";
/* A tool card's name without its badge (the Roth card carries "Beta"). */
function toolName(card){
  if (!card) return "";
  return Array.prototype.filter.call(card.childNodes, n => n.nodeType === 3)
    .map(n => n.textContent).join("").trim();
}
/* The tab title follows the view, so a row of open tabs or the history list
   says which tool each one is. */
/* Titles and descriptions for every page, in the JSON block in <head>
   (src/page-meta.json). The same table writes each address's static <head>
   (build.py), so the
   title a search engine reads and the one the app sets can't drift apart. */
let PAGE_META = null;
try { PAGE_META = JSON.parse($("pageMeta").textContent); } catch(e){}
/* Which page's article and title go with where the app is now: the tab or
   tool, or a landing alias like /rmd while you're still on its tool. */
function pageSlug(){
  const t = chartMode.tab;
  let slug = t === "simple" ? "home" : t === "single" ? "advanced" : t === "series" ? "stages"
    : t === "guide" ? "guide" : t === "about" ? "about"
    : t === "tools" ? (toolSub === "picker" ? "tools" : TOOL_PATHS[toolSub] || null) : null;
  const here = pathSeg(location.pathname);
  if (PATH_ALIAS[here] && slug && SUB_BY_PATH[slug] === PATH_ALIAS[here]) slug = here;
  return slug;
}
/* Each page ships with only its own article (build.py), so moving to another
   tool inside the app shows none rather than the wrong one. The page's one
   h1 is the tool's title in its header; elsewhere it's #pageH1, read by
   screen readers and search engines. A landing alias names the tool its
   own way (/72t is "72(t) Calculator"). Runs after setToolBack(). */
function seoSync(){
  const slug = pageSlug();
  document.querySelectorAll(".seo-a").forEach(a => { a.hidden = a.getAttribute("data-page") !== slug; });
  const P = PAGE_META && PAGE_META.pages[slug];
  const onTool = chartMode.tab === "tools" && toolSub !== "picker";
  $("pageH1").hidden = onTool;
  if (!onTool) $("pageH1").textContent = P && P.h1 ? P.h1 : "RetCalc";
  else if (P && P.h1) $("toolCrumb").textContent = P.h1;
}
function setDocTitle(){
  const P = PAGE_META && PAGE_META.pages[pageSlug()];
  if (P){ document.title = P.title; return; }
  const base = "RetCalc";
  const t = chartMode.tab;
  let name = "";
  if (t === "single") name = "Advanced";
  else if (t === "series") name = "Stages";
  else if (t === "about") name = "About";
  else if (t === "guide") name = "Retirement Readiness Guide";
  else if (t === "tools"){
    const card = document.querySelector('.toolcard[data-pick="' + toolSub + '"] .toolcard-name');
    name = toolSub === "picker" ? "Tools" : (toolName(card) || "Tools");
  }
  document.title = name ? name + " \u00b7 " + base : base;
}
function showTool(sub){
  toolSub = sub;
  const onPicker = (sub === "picker");
  setToolBack(sub);
  $("tab-toolpicker").hidden = !onPicker;
  $("tab-tax").hidden = (sub !== "tax");
  $("tab-mortgage").hidden = (sub !== "mortgage");
  $("tab-budget").hidden = (sub !== "budget");
  $("tab-college").hidden = (sub !== "college");
  $("tab-rentbuy").hidden = (sub !== "rentbuy");
  $("tab-drawdown").hidden = (sub !== "drawdown");
  $("tab-roth").hidden = (sub !== "roth");
  $("tab-debt").hidden = (sub !== "debt");
  $("tab-backtest").hidden = (sub !== "backtest");
  $("tab-healthcare").hidden = (sub !== "healthcare");
  $("tab-fire").hidden = (sub !== "fire");
  $("asideBT").hidden = (sub !== "backtest");
  $("tab-bridge").hidden = (sub !== "bridge");
  $("asideBR").hidden = (sub !== "bridge");
  $("tab-optimizer").hidden = (sub !== "optimizer");
  $("asideOP").hidden = (sub !== "optimizer");
  $("asideHC").hidden = (sub !== "healthcare");
  $("asideFire").hidden = (sub !== "fire");
  $("asideTax").hidden = (sub !== "tax");
  $("asideMort").hidden = (sub !== "mortgage");
  $("asideCollege").hidden = (sub !== "college");
  $("asideRB").hidden = (sub !== "rentbuy");
  $("asideDD").hidden = (sub !== "drawdown");
  $("asideRC").hidden = (sub !== "roth");
  // Budget has no sidebar inputs, so it earns the same full-width layout
  // as the tool picker rather than sitting narrow with empty space beside it.
  $("main").classList.toggle("solo", onPicker || sub === "budget" || sub === "debt");
  refreshScenarioList(currentScenario[activeTool()] || "");
  initCSVButtons();
  if (sub === "tax") renderTax();
  else if (sub === "mortgage") renderMort();
  else if (sub === "budget") renderBudget();
  else if (sub === "college") renderCollege();
  else if (sub === "rentbuy") renderRentBuy();
  else if (sub === "drawdown"){ renderDrawdown(); showDDIntro(); }
  else if (sub === "roth") renderRoth();
  else if (sub === "debt") renderDebt();
  else if (sub === "backtest") renderBacktest();
  else if (sub === "healthcare"){ if (hcReady) renderHealthcare(); }
  else if (sub === "bridge"){ if (brReady) renderBridge(); }
  else if (sub === "optimizer") renderOptimizer();
  else if (sub === "fire") {
    var fiEl = $("fiTarget");
    if (fiEl) fiEl.dispatchEvent(new Event("input", {bubbles:true}));
  }
  gdCoachSync();
  setDocTitle();
  try { window.scrollTo({top:0, behavior:"auto"}); } catch(e){ window.scrollTo(0, 0); }
  playPaneEnter();
}
/* Drawdown packs in more than any other tool, so first-time visitors get a
   one-line orientation. Dismissing it is remembered, same pattern as the
   theme preference. */
const DD_INTRO_KEY = "retcalc-dd-intro-seen";
function showDDIntro(){
  let seen = false;
  try { seen = localStorage.getItem(DD_INTRO_KEY) === "1"; } catch(e){}
  $("ddIntro").hidden = seen;
}
function dismissDDIntro(){
  $("ddIntro").hidden = true;
  try { localStorage.setItem(DD_INTRO_KEY, "1"); } catch(e){}
}
$("ddIntroClose").addEventListener("click", dismissDDIntro);
function showTab(t){
  chartMode.tab = t;
  $("tab-compare").hidden = true;
  $("tab-dd-compare").hidden = true;
  calcMenuClose(false);
  document.querySelectorAll("nav[role=tablist] button").forEach(x => {
    const k = x.getAttribute("data-tab");
    const on = k === t || (k === "calc" && CALC_MODES[t] != null);
    x.setAttribute("aria-selected", String(on));
    if (on) x.removeAttribute("tabindex"); else x.setAttribute("tabindex", "-1");
  });
  calcModeSync(t);
  $("tab-guide").hidden = (t !== "guide");
  $("tab-simple").hidden = (t !== "simple");
  $("tab-single").hidden = (t !== "single");
  $("tab-series").hidden = (t !== "series");
  $("tab-about").hidden = (t !== "about");
  hhPlace(t);
  // tools tab always delegates to showTool for pane visibility
  if (t !== "tools"){
    $("tab-toolpicker").hidden = true;
    $("tab-tax").hidden = true;
    $("tab-mortgage").hidden = true;
    $("tab-budget").hidden = true;
    $("asideTax").hidden = true;
    $("asideMort").hidden = true;
    $("asideCollege").hidden = true;
    $("asideRB").hidden = true;
    $("tab-college").hidden = true;
    $("tab-rentbuy").hidden = true;
    $("tab-drawdown").hidden = true;
    $("asideDD").hidden = true;
    $("tab-roth").hidden = true;
    $("asideRC").hidden = true;
    $("tab-debt").hidden = true;
    $("tab-backtest").hidden = true;
    $("tab-healthcare").hidden = true;
    $("tab-fire").hidden = true;
    $("asideBT").hidden = true;
    $("tab-bridge").hidden = true;
    $("asideBR").hidden = true;
    $("tab-optimizer").hidden = true;
    $("asideOP").hidden = true;
    $("asideHC").hidden = true;
    $("asideFire").hidden = true;
    $("main").classList.remove("solo");
  }
  if (t !== "tools") setToolBack("picker");
  $("asideSimple").hidden = (t !== "simple");
  $("asideSingle").hidden = (t !== "single");
  $("asideSeries").hidden = (t !== "series");
  $("main").classList.toggle("solo", t === "about" || t === "guide");
  refreshScenarioList(currentScenario[activeTool()] || "");
  if (t === "simple") renderBasic();
  else if (t === "single"){ if (lastRun) drawChart(lastRun, readInputs()); renderTools(); }
  else if (t === "series") renderSeries();
  else if (t === "guide") gdShow();
  else if (t === "tools") showTool(toolSub);
  if (t !== "tools"){ setDocTitle(); gdCoachSync(); }
  try { window.scrollTo({top:0, behavior:"auto"}); } catch(e){ window.scrollTo(0, 0); }
  if (t !== "tools") playPaneEnter();
}
const TABBTNS = Array.prototype.slice.call(
  document.querySelectorAll("nav[role=tablist] button"));
TABBTNS.forEach((b, i) => {
  b.addEventListener("click", e => {
    const t = b.getAttribute("data-tab");
    // With a mouse, Calculator goes to the mode last used (the menu opens
    // on hover); on a touch screen, a tap opens the mode menu.
    if (t === "calc"){
      if (calcHover() && e.detail !== 0){
        clearTimeout(calcHoverTimer);
        calcMenuClose(false);
        const m = calcLastMode();
        if (chartMode.tab !== m){ paneDir = "tab"; showTab(m); pushNav(); }
        return;
      }
      if ($("calcMenu").hidden) calcMenuOpen(e.detail === 0);
      else calcMenuClose(false);
      return;
    }
    // Clicking Tools while a tool is open → return to picker
    if (t === "tools" && chartMode.tab === "tools" && toolSub !== "picker"){
      paneDir = "back";
      showTool("picker");
    } else {
      showTab(t);
    }
    pushNav();
  });
  /* A tablist is expected to move on the arrow keys, with one stop in the tab
     order for the whole rail rather than one per tab. showTab keeps the
     tabindex roving as the selection changes. */
  b.addEventListener("keydown", e => {
    if (b === CALCBTN && (e.key === "ArrowDown" || e.key === "ArrowUp")){
      e.preventDefault();
      calcMenuOpen(true);
      return;
    }
    let j = -1;
    if (e.key === "ArrowRight") j = (i + 1) % TABBTNS.length;
    else if (e.key === "ArrowLeft") j = (i - 1 + TABBTNS.length) % TABBTNS.length;
    else if (e.key === "Home") j = 0;
    else if (e.key === "End") j = TABBTNS.length - 1;
    if (j < 0) return;
    e.preventDefault();
    calcMenuClose(false);
    TABBTNS[j].focus();
    // Arrowing onto Calculator only lands there; opening its menu on the way
    // past would get in the way of reaching Tools.
    if (TABBTNS[j] !== CALCBTN) TABBTNS[j].click();
  });
});
document.querySelectorAll(".toolcard[data-pick]").forEach(card => {
  const go = () => {
    if (chartMode.tab !== "tools") showTab("tools");
    paneDir = "fwd";
    showTool(card.getAttribute("data-pick"));
    pushNav();
  };
  /* Where the browser can, the card's icon tile glides up into the tool's
     header as the page changes (a view transition naming the one tile on
     each side); elsewhere, or with reduced motion, the page just changes. */
  const activate = () => {
    const ic = card.querySelector(".toolcard-icon");
    let motion = true;
    try { motion = !window.matchMedia("(prefers-reduced-motion: reduce)").matches; } catch(e){}
    if (!document.startViewTransition || !motion || !ic){ go(); return; }
    ic.style.viewTransitionName = "toolicon";
    let vt;
    try {
      vt = document.startViewTransition(() => {
        ic.style.viewTransitionName = "";
        go();
        $("toolHeadIcon").style.viewTransitionName = "toolicon";
      });
    } catch(e){ ic.style.viewTransitionName = ""; go(); return; }
    const done = () => { $("toolHeadIcon").style.viewTransitionName = ""; ic.style.viewTransitionName = ""; };
    // A transition the browser skips (a hidden tab, say) still runs the
    // update; its promises just reject, which is expected, not an error.
    vt.ready.catch(() => {});
    vt.updateCallbackDone.catch(() => {});
    vt.finished.then(done, done);
  };
  card.addEventListener("click", activate);
  card.addEventListener("keydown", e => {
    if (e.key === "Enter" || e.key === " "){ e.preventDefault(); activate(); }
  });
});



/* ---------- one-page summary ---------- */
/* Built on demand into a light-themed sheet that only the print stylesheet
   shows, so the browser's own "Save as PDF" does the export. No dependencies,
   and it works on iOS through Share > Print. */
/* The chart emits structural colors from the active theme, so the print swap is
   built at call time from the current variable values mapped to a fixed light
   palette. This keeps the sheet readable whichever theme is on screen. */
function lighten(node){
  const swap = {};
  swap[cssVar("--grid").toLowerCase()] = "#e2e5e3";
  swap[cssVar("--axis").toLowerCase()] = "#666e73";
  swap[cssVar("--stageline").toLowerCase()] = "#9aa5ab";
  swap[cssVar("--dotstroke").toLowerCase()] = "#ffffff";
  swap[cssVar("--bg").toLowerCase()] = "#ffffff";
  const walk = nd => {
    ["stroke","fill"].forEach(a => {
      const v = nd.getAttribute && nd.getAttribute(a);
      if (v && swap[v.toLowerCase()]) nd.setAttribute(a, swap[v.toLowerCase()]);
    });
    for (let i = 0; i < nd.childNodes.length; i++) walk(nd.childNodes[i]);
  };
  walk(node);
}
function row(k, v){ return "<div class='sh-r'><span>" + k + "</span><b>" + v + "</b></div>"; }

/* Split by account type, the summary lists the three starting balances
   rather than one total. */
function acSheetRows(a, total){
  if (!a) return row("Starting value", money(total));
  return row("Traditional balance", money(a.tradBal)) + row("Roth balance", money(a.rothBal)) +
    row("Brokerage balance", money(a.brokBal));
}
/* The printed summaries carry the logo beside their title, in the deeper
   light-theme hues so it holds up on paper. */
const SHEET_MARK = "<svg class='sh-mark' viewBox='4 4 56 56' aria-hidden='true'><g transform='rotate(-45 32 32)'>" +
  "<path d='M33 7 L11.5 28.5 M33 57 L11.5 35.5' fill='none' stroke='#5a81c3' stroke-width='2'/>" +
  "<path d='M33 7 C31 10 34 13 39 17 Q53 32 39 47 C34 51 31 54 33 57' fill='none' stroke='#2a9e73' stroke-width='4.5' stroke-linecap='round' stroke-linejoin='round'/>" +
  "<path d='M7 32 H51' stroke='#c1861e' stroke-width='3.2' stroke-linecap='round'/>" +
  "<path d='M60 32 L48 25.5 L50.5 32 L48 38.5 Z M11 32 L6 25.5 H11 L18 32 Z M11 32 L6 38.5 H11 L18 32 Z' fill='#c1861e'/></g></svg>";

function buildSheet(){
  if (!$("tab-guide").hidden) return gdGuideSheet();
  if (!$("tab-tax").hidden) return buildTaxSheet();
  if (!$("tab-mortgage").hidden) return buildMortSheet();
  if (!$("tab-budget").hidden) return buildBudgetSheet();
  if (!$("tab-college").hidden) return buildCollegeSheet();
  if (!$("tab-rentbuy").hidden) return buildRentBuySheet();
  if (!$("tab-drawdown").hidden) return buildDrawdownSheet();
  if (!$("tab-roth").hidden) return buildRothSheet();
  if (!$("tab-bridge").hidden) return buildBridgeSheet();
  if (!$("tab-debt").hidden) return buildDebtSheet();
  if (!$("tab-simple").hidden) return buildBasicSheet();
  const series = !$("tab-series").hidden;
  const g = readGlobals(), p = readInputs();
  const R = series ? projectSeries(g, effectiveStages(g)) : project(p);
  const infl = series ? g.inflation : p.inflation;
  const years = series ? R.totalYears : p.years;

  let inputs = "";
  if (series){
    inputs += acSheetRows(g.acct, g.initial);
    inputs += row("Inflation", pctStr(g.inflation, 2));
    inputs += row("Withdrawal rate", pctStr(g.withdrawal, 2));
    inputs += row(g.acct ? "Tax on withdrawals, calculated" : "Effective tax rate", pctStr(g.taxRate, 2));
    if (g.fees > 0) inputs += row("Fees", pctStr(g.fees, 2));
    // Capped so a plan with many stages can't push the sheet onto a second
    // page; a "+N more" line is honest about what got left off.
    const allStages = effectiveStages(g);
    allStages.slice(0, 5).forEach((st, i) => {
      inputs += row("Stage " + (i+1) + " &middot; " + fmtNum(st.years) + " yrs",
        money(st.contrib, 0) + " " + st.period.toLowerCase() + " @ " + pctStr(st.nominal, 2));
    });
    if (allStages.length > 5)
      inputs += "<div class='sh-more'>+ " + (allStages.length - 5) + " more stage" +
        (allStages.length - 5 === 1 ? "" : "s") + "</div>";
  } else {
    inputs += acSheetRows(p.acct, p.initial);
    inputs += row(p.acct ? "Contribution, with match" : "Contribution", money(p.contrib, 2) + " " + p.period.toLowerCase());
    inputs += row("Contribution growth", pctStr(p.growth, 2) + " / yr" +
      (p.acct && p.acct.gRates ? " blended (traditional " + pctStr(p.acct.gRates.t, 2) +
        ", Roth " + pctStr(p.acct.gRates.r, 2) + ", taxable " + pctStr(p.acct.gRates.b, 2) + ")" : ""));
    inputs += row("Time period", fmtNum(p.years) + " years");
    inputs += row("Rate of return", pctStr(p.gross, 2));
    if (p.fees > 0) inputs += row("Fees", "\u2212" + pctStr(p.fees, 2));
    inputs += row("Inflation", pctStr(p.inflation, 2));
    inputs += row("Withdrawal rate", pctStr(p.withdrawal, 2));
    inputs += row(p.acct ? "Tax on withdrawals, calculated" : "Effective tax rate", pctStr(p.taxRate, 2));
  }

  let out = "";
  out += row("Amount invested", money(R.invested));
  out += row("Growth", money(R.growth));
  const lastPer = series ? R.lastPeriod : p.period;
  out += row("Final contribution, inflation adj.", lastPer
    ? money(R.lastContribReal) + " " + PERIOD_ADV[lastPer] : money(0));
  out += row("Future value", money(R.fv));
  out += row("Inflation adjusted", money(R.fvReal));
  out += row("Annual withdrawal", money(R.wdReal) + " (adj.)");
  out += row("After tax, per year", money(R.afterTax));
  out += row("After tax, per month", money(R.afterTaxMo));

  const rows = series
    ? R.calRows.map(r => ({year:r.year, end:r.end, growth:r.growth, contrib:r.contrib}))
    : R.years.map(y => ({year:y.year, end:y.end, growth:y.growth, contrib:y.contrib}));
  const cross = rows.find(r => r.growth > r.contrib && r.contrib > 0);
  let ms = row("Crossover year", cross ? "Year " + fmtNum(cross.year) : "\u2014");
  MS_LADDER.filter(v => v <= R.fv).slice(-4).forEach(v => {
    const hit = rows.find(r => r.end >= v);
    ms += row("Reaches " + money(v), hit ? "Year " + fmtNum(hit.year) : "\u2014");
  });

  // Goal-solve and Coast FIRE, single-run only \u2014 this is where they live
  // on screen, and both are genuinely useful reference numbers when present.
  let goalSection = "";
  if (!series){
    const solveFor = $("solveFor").value;
    const S = goalSolve(acSolveP(p), solveFor, num("target"));
    const C = coastFire(p, S.portFuture);
    let goal = row("Target", solveFor === "After-Tax Withdrawal"
      ? money(num("target")) + "/yr after tax" : money(num("target")));
    goal += row("Portfolio needed", money(S.portToday));
    goal += row("Raise contribution to", money(S.perPeriod, 2) + " " + p.period.toLowerCase());
    goal += row("Or extend timeline to", solveYears(p, S.portToday).reached
      ? fmtYears(solveYears(p, S.portToday).years) : "Not reached in 100 yrs");
    goal += row("Coast FIRE", C.state === "already" ? "Already there" :
      C.state === "reachable" ? fmtYears(C.years) : "Not on track");
    goalSection = "<section><div class='sh-t'>Working toward a target</div>" + goal + "</section>";
  }

  // Compact year-by-year, sampled if long.
  const step = rows.length <= 15 ? 1 : rows.length <= 30 ? 2 : 3;
  const tableRows = rows.filter((r, i) => i === 0 || i === rows.length - 1 || i % step === 0);
  let table = "<table><thead><tr><th>Year</th><th>Contributed</th><th>Growth</th>" +
    "<th>Balance</th><th>In today's $</th></tr></thead><tbody>";
  const defl = series ? g.inflation : p.inflation;
  tableRows.forEach(r => {
    table += "<tr><td>" + r.year + "</td><td>" + money(r.contrib) + "</td><td>" +
      money(r.growth) + "</td><td>" + money(r.end) + "</td><td>" +
      money(r.end / Math.pow(1 + defl, r.year)) + "</td></tr>";
  });
  table += "</tbody></table>";

  const src = $(series ? "chartS" : "chart");
  let chart = "";
  if (src && src.childNodes.length){
    const clone = src.cloneNode(true);
    lighten(clone);
    clone.removeAttribute("style");
    chart = "<div class='sh-chart'>" + clone.outerHTML + "</div>";
  }

  const mode = (series ? chartMode.series : chartMode.single) === "mc"
    ? "Monte Carlo, " + readTrials(series ? "trialsS" : "trials").toLocaleString() + " runs"
    : "Projection";

  $("sheet").innerHTML =
    "<div class='sh-h'>" + SHEET_MARK + "<h1>Investment Projection</h1>" +
      "<span>" + (series ? "Stages" : "Advanced") + " &middot; " +
      fmtNum(years) + " years &middot; " + mode + "</span></div>" +
    "<div class='sh-big'>" +
      "<div><div class='k'>Future value</div><div class='v'>" + money(R.fv) + "</div>" +
        "<div class='n'>after " + fmtNum(years) + " years</div></div>" +
      "<div><div class='k'>Inflation adjusted</div><div class='v'>" + money(R.fvReal) + "</div>" +
        "<div class='n'>in today's spending power</div></div>" +
      "<div><div class='k'>After-tax income / yr</div><div class='v'>" + money(R.afterTax) + "</div>" +
        "<div class='n'>first year of retirement</div></div>" +
    "</div>" +
    chart +
    "<div class='sh-cols'>" +
      "<section><div class='sh-t'>Assumptions</div>" + inputs + "</section>" +
      "<section><div class='sh-t'>Results</div>" + out + "</section>" +
      "<section><div class='sh-t'>Milestones</div>" + ms + "</section>" +
      goalSection +
    "</div>" +
    "<div class='sh-table'><div class='sh-t'>Year by year</div>" + table + "</div>" +
    "<div class='sh-foot'>Figures are projections generated from the assumptions listed " +
    "above, not predictions. Past performance does not predict future returns. " +
    "This is not financial advice.</div>";
}
function buildTaxSheet(){
  const inp = readTax();
  if (!(inp.gross + inp.gross2 > 0)){ $("sheet").innerHTML = ""; toast("Enter your income first"); return false; }
  const R = runTax(inp);
  const ret = inp.mode === "retire";
  let inputs = "";
  if (ret){
    if (inp.trad > 0) inputs += row("Traditional withdrawal", money(inp.trad));
    if (inp.roth > 0) inputs += row("Roth withdrawal", money(inp.roth));
    if (inp.brok > 0) inputs += row("Brokerage withdrawal",
      money(inp.brok) + " (" + pctStr(inp.gainPct, 0) + " gain)");
    if (inp.ss > 0) inputs += row("Social Security", money(inp.ss));
    if (inp.pension > 0) inputs += row("Pension / annuity", money(inp.pension) +
      (inp.penPublic ? " (government)" : " (private)"));
    if (inp.other > 0) inputs += row("Other ordinary income", money(inp.other));
    inputs += row("Gross income", money(R.gross));
  } else if (inp.status === "m"){
    inputs += row("Your gross income", money(inp.gross));
    inputs += row("Spouse's gross income", money(inp.gross2));
    inputs += row("Household gross income", money(R.gross));
  } else {
    inputs += row("Gross income", money(inp.gross));
  }
  inputs += row("Filing status", inp.status === "m" ? "Married filing jointly" : "Single");
  if (ret && R.seniors > 0) inputs += row("Age 65 or older",
    R.seniors === 2 ? "Both spouses" : "Yes");
  inputs += row("State", R.stateName || "None");
  if (inp.pre > 0) inputs += row("Pre-tax deductions", money(inp.pre));
  inputs += row("Deduction", inp.dedType === "item"
    ? "Itemized (" + money(inp.item) + ")"
    : "Standard (" + money(ret ? R.fedDed : FED_STD[inp.status]) + ")");
  if (ret && R.ssGross > 0) inputs += row("Taxable Social Security", money(R.taxableSS));
  inputs += row("Taxable income", money(R.fedTaxable));

  let out;
  if (ret){
    out = row("Federal, ordinary income", money(R.fedOrdinary));
    out += row("Federal, long-term gains", money(R.ltcg) +
      (R.gainTaxable > 0 ? " (" + pctStr(R.ltcgRate, 1) + ")" : ""));
    if (R.niit > 0) out += row("Net investment income tax", money(R.niit));
    out += row("State tax", money(R.state));
    out += row("Total tax", money(R.total));
    out += row("Effective rate", pctStr(R.effTotal, 1));
    out += row("Marginal rate", pctStr(R.marginal, 1));
  } else {
    out = row("Federal tax", money(R.federal));
    out += row("State tax", money(R.state));
    if (inp.status === "m"){
      out += row("Your Social Security", money(R.ss1));
      out += row("Spouse's Social Security", money(R.ss2));
    } else {
      out += row("Social Security", money(R.ss));
    }
    out += row("Medicare" + (R.addl > 0 ? " (+ surtax)" : ""), money(R.med + R.addl));
    out += row("Total tax", money(R.total));
    out += row("Effective rate", pctStr(R.effTotal, 1));
    out += row("Marginal rate", pctStr(R.marginal, 0));
  }

  let pay;
  if (ret){
    pay = row("Income after tax, per year", money(R.net));
    pay += row("Per month", money(R.net / 12));
    if (R.gain > 0) pay += row("Gain realized", money(R.gain));
    if (R.zeroRoom > 0) pay += row("Room left in 0% band", money(R.zeroRoom));
  } else {
    pay = row("Take-home, per year", money(R.net));
    pay += row("Per month", money(R.net / 12));
    pay += row("Per biweekly check", money(R.net / 26));
    const netPay = R.gross - R.total;
    if (inp.pre > 0) pay += row("Net pay (before pre-tax)", money(netPay));
  }

  const src = $("txPie");
  let chart = "";
  if (src && src.childNodes.length){
    const clone = src.cloneNode(true);
    lighten(clone); clone.removeAttribute("style");
    chart = "<div class='sh-chart' style='width:1.5in;flex:none;margin:0'>" + clone.outerHTML + "</div>";
  }

  // Full federal bracket table \u2014 genuinely useful reference material that
  // fits comfortably given how few rows federal brackets have.
  let table = "<table><thead><tr><th>Rate</th><th>Income range</th><th>Taxed in band</th><th>Tax</th></tr></thead><tbody>";
  R.bands.forEach(b => {
    table += "<tr" + (b.amount > 0 ? "" : " style='color:#bbb'") + "><td>" + pctStr(b.rate, 0) +
      "</td><td>" + money(b.lo) + (b.hi === Infinity ? " and up" : " \u2013 " + money(b.hi)) +
      "</td><td>" + money(b.amount) + "</td><td>" + money(b.tax) + "</td></tr>";
  });
  table += "</tbody></table>";

  $("sheet").innerHTML =
    "<div class='sh-h'>" + SHEET_MARK + "<h1>" + (ret ? "Retirement Tax Summary" : "Income Tax Summary") +
      "</h1><span>Tax year 2026</span></div>" +
    "<div class='sh-big'>" +
      "<div><div class='k'>" + (ret ? "Income after tax" : "Take-home pay") +
        "</div><div class='v'>" + money(R.net) +
        "</div><div class='n'>per year</div></div>" +
      "<div><div class='k'>Total tax</div><div class='v'>" + money(R.total) +
        "</div><div class='n'>" + pctStr(R.effTotal, 1) + " effective</div></div>" +
      "<div><div class='k'>Per month</div><div class='v'>" + money(R.net / 12) +
        "</div><div class='n'>" + (ret ? "after tax" : "take-home") + "</div></div>" +
    "</div>" +
    "<div style='display:flex;gap:16px;margin-bottom:10px;align-items:stretch'>" + chart +
      "<div style='flex:1;display:flex;gap:16px'>" +
        "<section style='flex:1'><div class='sh-t'>Your situation</div>" + inputs + "</section>" +
        "<section style='flex:1'><div class='sh-t'>Tax breakdown</div>" + out + "</section>" +
        "<section style='flex:1'><div class='sh-t'>" + (ret ? "What you keep" : "Paycheck") + "</div>" + pay + "</section>" +
      "</div>" +
    "</div>" +
    "<div class='sh-table'><div class='sh-t'>Federal tax brackets</div>" + table + "</div>" +
    "<div class='sh-foot'>Based on published 2026 federal and state rates. Omits credits, " +
    "local taxes and many special cases. Not tax advice.</div>";
}

function buildMortSheet(){
  const m = readMort();
  if (!(m.price > 0)){ $("sheet").innerHTML = ""; toast("Enter a home price first"); return false; }
  const R = mortgage(m);
  let inputs = row("Home price", money(m.price));
  inputs += row("Down payment", money(m.down) + " (" + pctStr(m.price ? m.down / m.price : 0, 0) + ")");
  inputs += row("Loan amount", money(R.loan));
  inputs += row("Interest rate", pctStr(m.rate, 2));
  inputs += row("Term", fmtNum(m.term) + " years");
  if (R.pmi > 0) inputs += row("PMI", money(R.pmi) + "/mo until 20% equity");

  let pay = row("Principal & interest", money(R.pi));
  pay += row("Property tax", money(R.tax));
  pay += row("Insurance", money(R.ins));
  if (R.pmi > 0) pay += row("PMI", money(R.pmi));
  if (R.maint > 0) pay += row("Maintenance", money(R.maint));
  if (R.util > 0) pay += row("Utilities", money(R.util));
  if (R.hoa > 0) pay += row("HOA", money(R.hoa));
  pay += row("Total monthly payment", money(R.total));

  let out = row("Total interest paid", money(R.totalInterest));
  out += row("Total cost of loan", money(R.loan + R.totalInterest));
  if (R.pmiPaid > 0) out += row("Total PMI paid", money(R.pmiPaid));
  const halfwayYear = R.years.findIndex(y => y.balance <= R.loan / 2) + 1;
  if (halfwayYear > 0) out += row("Halfway point (balance)", "Year " + halfwayYear);
  out += row("Payoff", moWhen(R.payoffMonth));

  if (R.extraActive){
    const base = mortgage(Object.assign({}, m, {extraMonthly:0, extraOnce:0,
      extraOnceMonth:0, recast:false}));
    out += row("With extra payments", moDur(base.payoffMonth - R.payoffMonth) +
      " sooner, " + money(base.totalInterest - R.totalInterest) + " less interest");
    if (R.recastPI != null) out += row("Payment after recast", money(R.recastPI) + "/mo");
  }
  if (m.refiOn){
    const RF = refiCompare(m, {rate:m.refiRate, term:m.refiTerm, cost:m.refiCost});
    out += row("Refinance to " + pctStr(m.refiRate, 2) + ", " + fmtNum(m.refiTerm) + "yr",
      money(RF.then.pi) + "/mo, breaks even in " +
      (RF.breakEvenMonths == null ? "never" :
       RF.breakEvenMonths <= 0 ? "immediately" : moDur(RF.breakEvenMonths)) +
      ", " + (RF.lifetimeDelta >= 0 ? "saves " : "costs ") + money(Math.abs(RF.lifetimeDelta)) +
      " lifetime");
  }

  const src = $("chartMo");
  let chart = "";
  if (src && src.childNodes.length){
    const clone = src.cloneNode(true);
    lighten(clone); clone.removeAttribute("style");
    chart = "<div class='sh-chart'>" + clone.outerHTML + "</div>";
  }

  // Amortization, sampled so a 30-year loan doesn't spill onto a second page.
  const step = R.years.length <= 15 ? 1 : R.years.length <= 30 ? 2 : 3;
  const tableRows = R.years.filter((y, i) => i === 0 || i === R.years.length - 1 || i % step === 0);
  let table = "<table><thead><tr><th>Year</th><th>Interest</th><th>Principal</th>" +
    "<th>Total paid</th><th>Balance</th></tr></thead><tbody>";
  tableRows.forEach(y => {
    table += "<tr><td>" + y.year + "</td><td>" + money(y.interest) + "</td><td>" +
      money(y.principal) + "</td><td>" + money(y.paid) + "</td><td>" + money(y.balance) + "</td></tr>";
  });
  table += "</tbody></table>";

  $("sheet").innerHTML =
    "<div class='sh-h'>" + SHEET_MARK + "<h1>Mortgage Summary</h1><span>" + fmtNum(m.term) + " year term</span></div>" +
    "<div class='sh-big'>" +
      "<div><div class='k'>Monthly payment</div><div class='v'>" + money(R.total) +
        "</div><div class='n'>all in</div></div>" +
      "<div><div class='k'>Loan amount</div><div class='v'>" + money(R.loan) +
        "</div><div class='n'>" + pctStr(m.price ? m.down / m.price : 0, 0) + " down</div></div>" +
      "<div><div class='k'>Total interest</div><div class='v'>" + money(R.totalInterest) +
        "</div><div class='n'>over the loan</div></div>" +
    "</div>" + chart +
    "<div class='sh-cols'>" +
      "<section><div class='sh-t'>The loan</div>" + inputs + "</section>" +
      "<section><div class='sh-t'>Monthly payment</div>" + pay + "</section>" +
      "<section><div class='sh-t'>Over the life of the loan</div>" + out + "</section>" +
    "</div>" +
    "<div class='sh-table'><div class='sh-t'>Amortization</div>" + table + "</div>" +
    "<div class='sh-foot'>Rate and costs are estimates. Actual terms depend on credit, " +
    "lender and location. Not a loan offer.</div>";
}

function buildCollegeSheet(){
  const inp = readCollege();
  if (inp.kids.length > 1) return buildCollegeFamilySheet(inp);
  if (!(inp.annualCost > 0)){ $("sheet").innerHTML = ""; toast("Set an annual cost first"); return false; }
  const R = collegeSavingsCalc(inp);
  let inputs = row("Annual cost today", money(inp.annualCost));
  inputs += row("Years until college", fmtNum(inp.yearsUntil));
  inputs += row("Years of college", fmtNum(inp.collegeYrs));
  inputs += row("Currently saved", money(inp.saved));
  inputs += row("Investment return", pctStr(inp.investRet, 1));
  inputs += row("Tuition inflation", pctStr(inp.tuitionInfl, 1));

  let out = row("Total cost, all years", money(R.totalFuture));
  out += row("Savings grow to", money(R.savingsAtStart));
  out += row("Needed when college starts", money(R.targetAtStart));
  out += row("Shortfall to close", money(R.shortfall));
  out += row("Monthly savings needed", money(R.monthly));

  // What each year of college actually costs, inflated to when it happens.
  let costs = "";
  R.yearCosts.forEach((c, i) => { costs += row("College year " + (i+1), money(c)); });

  const src = $("chartCl");
  let chart = "";
  if (src && src.childNodes.length){
    const clone = src.cloneNode(true);
    lighten(clone); clone.removeAttribute("style");
    chart = "<div class='sh-chart'>" + clone.outerHTML + "</div>";
  }

  // Savings accumulation, sampled if the horizon is long.
  const step = R.rows.length <= 15 ? 1 : R.rows.length <= 30 ? 2 : 3;
  const tableRows = R.rows.filter((r, i) => i === 0 || i === R.rows.length - 1 || i % step === 0);
  let table = "<table><thead><tr><th>Year</th><th>Contributed</th><th>Growth</th>" +
    "<th>Balance</th></tr></thead><tbody>";
  tableRows.forEach(r => {
    table += "<tr><td>" + r.year + "</td><td>" + money(r.contribs) + "</td><td>" +
      money(r.growth) + "</td><td>" + money(r.balance) + "</td></tr>";
  });
  table += "</tbody></table>";

  $("sheet").innerHTML =
    "<div class='sh-h'>" + SHEET_MARK + "<h1>College Savings Plan</h1><span>" + fmtNum(inp.yearsUntil) + " years to go</span></div>" +
    "<div class='sh-big'>" +
      "<div><div class='k'>Save per month</div><div class='v'>" + money(R.monthly) +
        "</div><div class='n'>to close the gap</div></div>" +
      "<div><div class='k'>Total cost, all years</div><div class='v'>" + money(R.totalFuture) +
        "</div><div class='n'>" + fmtNum(inp.collegeYrs) + " years</div></div>" +
      "<div><div class='k'>Needed when college starts</div><div class='v'>" + money(R.targetAtStart) +
        "</div><div class='n'>present value</div></div>" +
    "</div>" + chart +
    "<div class='sh-cols'>" +
      "<section><div class='sh-t'>Assumptions</div>" + inputs + "</section>" +
      "<section><div class='sh-t'>Results</div>" + out + "</section>" +
      "<section><div class='sh-t'>Cost by college year</div>" + costs + "</section>" +
    "</div>" +
    "<div class='sh-table'><div class='sh-t'>Savings accumulation</div>" + table + "</div>" +
    "<div class='sh-foot'>Excludes financial aid, scholarships and 529 tax advantages. " +
    "Tuition inflation is an assumption, not a guarantee.</div>";
}

function buildCollegeFamilySheet(inp){
  const P = collegePlanCalc(inp);
  if (!P){ $("sheet").innerHTML = ""; toast("Set an annual cost first"); return false; }
  const n = P.kids.length;
  let kids = "";
  inp.kids.forEach((k, i) => {
    kids += row("Child " + (i + 1), k.annualCost > 0 && k.yearsUntil > 0
      ? money(k.annualCost) + "/yr today, in " + fmtNum(k.yearsUntil) + " yrs, for " + fmtNum(k.collegeYrs)
      : "left out");
  });
  let inputs = row("Currently saved", money(inp.saved));
  inputs += row("Investment return", pctStr(inp.investRet, 1));
  inputs += row("Tuition inflation", pctStr(inp.tuitionInfl, 1));

  let out = row("Total cost, all children", money(P.totalFuture));
  out += row("Needed today", money(P.pvToday));
  P.phases.forEach((x, i) => {
    out += row(i ? "Then, from year " + fmtNum(Math.round(x.from / 12 * 10) / 10) : "Monthly savings needed", money(x.monthly) + "/mo");
  });
  P.kids.forEach(k => { out += row("Child " + (k.index + 1) + ", all years", money(k.total)); });

  const src = $("chartCl");
  let chart = "";
  if (src && src.childNodes.length){
    const clone = src.cloneNode(true);
    lighten(clone); clone.removeAttribute("style");
    chart = "<div class='sh-chart'>" + clone.outerHTML + "</div>";
  }
  const step = P.rows.length <= 15 ? 1 : P.rows.length <= 30 ? 2 : 3;
  const tableRows = P.rows.filter((r, i) => i === 0 || i === P.rows.length - 1 || i % step === 0 || r.paid > 0);
  let table = "<table><thead><tr><th>Year</th><th>Contributed</th><th>Growth</th>" +
    "<th>Paid for college</th><th>Balance</th></tr></thead><tbody>";
  tableRows.forEach(r => {
    table += "<tr><td>" + r.year + "</td><td>" + money(r.contribs) + "</td><td>" +
      money(r.growth) + "</td><td>" + (r.paid > 0 ? money(r.paid) : "\u2014") + "</td><td>" + money(r.balance) + "</td></tr>";
  });
  table += "</tbody></table>";

  $("sheet").innerHTML =
    "<div class='sh-h'>" + SHEET_MARK + "<h1>College Savings Plan</h1><span>" + fmtNum(n) + " children</span></div>" +
    "<div class='sh-big'>" +
      "<div><div class='k'>Save per month</div><div class='v'>" + money(P.monthly) +
        "</div><div class='n'>" + collegePhaseNote(P) + "</div></div>" +
      "<div><div class='k'>Total cost, all children</div><div class='v'>" + money(P.totalFuture) +
        "</div><div class='n'>at future prices</div></div>" +
      "<div><div class='k'>Needed today</div><div class='v'>" + money(P.pvToday) +
        "</div><div class='n'>present value</div></div>" +
    "</div>" + chart +
    "<div class='sh-cols'>" +
      "<section><div class='sh-t'>Children</div>" + kids + "</section>" +
      "<section><div class='sh-t'>Assumptions</div>" + inputs + "</section>" +
      "<section><div class='sh-t'>Results</div>" + out + "</section>" +
    "</div>" +
    "<div class='sh-table'><div class='sh-t'>One account for all of them</div>" + table + "</div>" +
    "<div class='sh-foot'>Excludes financial aid, scholarships and 529 tax advantages. " +
    "Tuition inflation is an assumption, not a guarantee.</div>";
}

function buildRentBuySheet(){
  const inp = readRB();
  if (!(inp.price > 0)){ $("sheet").innerHTML = ""; toast("Enter a home price first"); return false; }
  const R = rentBuyCalc(inp);
  const last = R.years[R.years.length - 1];
  if (!last){ $("sheet").innerHTML = ""; return false; }
  const buyWins = last.buyerNW >= last.renterNW;

  let inputs = row("Home price", money(inp.price));
  inputs += row("Down payment", pctStr(inp.downPct / 100, 0));
  inputs += row("Interest rate", pctStr(inp.rate / 100, 2));
  inputs += row("Loan term", fmtNum(inp.term) + " years");
  inputs += row("Monthly rent (start)", money(inp.rent));
  inputs += row("Rent increase", pctStr(inp.rentInc / 100, 1) + "/yr");
  inputs += row("Home appreciation", pctStr(inp.appr / 100, 1) + "/yr");
  inputs += row("Investment return", pctStr(inp.invest / 100, 1) + "/yr");
  inputs += row("Time horizon", fmtNum(inp.horizon) + " years");

  let out = row("Buyer net worth", money(last.buyerNW));
  out += row("Renter net worth", money(last.renterNW));
  out += row("Difference", (buyWins ? "+" : "\u2212") + money(Math.abs(last.buyerNW - last.renterNW)));
  out += row("Break-even point", R.breakEven ? "Year " + fmtNum(R.breakEven) : "Not within horizon");
  out += row("Renter invests upfront", money(R.initialInvest));
  out += row("Monthly cost, buying", money(R.monthlyBuy));
  out += row("Monthly cost, renting", money(inp.rent) + " (starting)");
  out += row("Home value at end", money(last.homeVal));
  out += row("Mortgage balance at end", money(last.balance));

  const src = $("chartRB");
  let chart = "";
  if (src && src.childNodes.length){
    const clone = src.cloneNode(true);
    lighten(clone); clone.removeAttribute("style");
    chart = "<div class='sh-chart'>" + clone.outerHTML + "</div>";
  }

  // Year-by-year net worth, sampled if the horizon is long, always keeping
  // the actual break-even year even if sampling would otherwise skip it.
  const step = R.years.length <= 15 ? 1 : R.years.length <= 30 ? 2 : 3;
  const tableRows = R.years.filter((y, i) =>
    i === 0 || i === R.years.length - 1 || i % step === 0 || y.year === R.breakEven);
  let table = "<table><thead><tr><th>Year</th><th>Buyer NW</th><th>Renter NW</th>" +
    "<th>Home value</th><th>Balance</th></tr></thead><tbody>";
  tableRows.forEach(y => {
    const isBE = y.year === R.breakEven;
    table += "<tr" + (isBE ? " style='font-weight:700;background:#f5f0e0'" : "") + "><td>" + y.year +
      (isBE ? " \u2605" : "") + "</td><td>" + money(y.buyerNW) + "</td><td>" + money(y.renterNW) +
      "</td><td>" + money(y.homeVal) + "</td><td>" + money(y.balance) + "</td></tr>";
  });
  table += "</tbody></table>";

  $("sheet").innerHTML =
    "<div class='sh-h'>" + SHEET_MARK + "<h1>Rent vs. Buy</h1><span>After " + fmtNum(inp.horizon) + " years</span></div>" +
    "<div class='sh-big'>" +
      "<div><div class='k'>Better choice</div><div class='v'>" + (buyWins ? "Buying" : "Renting") +
        "</div><div class='n'>by " + money(Math.abs(last.buyerNW - last.renterNW)) + "</div></div>" +
      "<div><div class='k'>Buyer net worth</div><div class='v'>" + money(last.buyerNW) +
        "</div><div class='n'>after " + fmtNum(inp.horizon) + " years</div></div>" +
      "<div><div class='k'>Renter net worth</div><div class='v'>" + money(last.renterNW) +
        "</div><div class='n'>after " + fmtNum(inp.horizon) + " years</div></div>" +
    "</div>" + chart +
    "<div class='sh-cols'>" +
      "<section><div class='sh-t'>Assumptions</div>" + inputs + "</section>" +
      "<section><div class='sh-t'>Results</div>" + out + "</section>" +
    "</div>" +
    "<div class='sh-table'><div class='sh-t'>Net worth by year" +
      (R.breakEven ? " &middot; \u2605 marks the break-even year" : "") + "</div>" + table + "</div>" +
    "<div class='sh-foot'>Property tax, insurance and maintenance grow with home value; PMI is included above 80% loan-to-value. " +
    "Excludes the mortgage interest deduction and non-financial factors " +
    "like stability. Projections, not predictions.</div>";
}

function buildDrawdownSheet(){
  const o = readDD();
  ddRetireAge = o.retireAge;
  if (!(o.initial > 0)){ $("sheet").innerHTML = ""; toast("Enter a portfolio value first"); return false; }
  const H = historicalBacktest(o);
  const show = H.runs.filter(r => r.startIdx === ddSelStart)[0] || H.firstFail || H.runs[0];
  const showLabel = ddStartLabel(show, H.monthly);

  let inputs = row("Starting portfolio", money(o.initial));
  inputs += row("Years in retirement", fmtNum(o.years));
  inputs += row("Asset mix", ddMixText(o));
  if (o.rebal !== "year") inputs += row("Rebalancing", ddRebalText(o));
  ddPlanRows(o).forEach(r => { inputs += row(r[0], r[1]); });
  if (o.ssAnnual > 0 || o.ssAnnual2 > 0) inputs += row("Social Security", money(o.ssAnnualTotal) + "/yr");
  (o.incomeItems || []).filter(it => it.on !== false).forEach(it => inputs += row(it.name, describeItem(it)));
  (o.expenseItems || []).filter(it => it.on !== false).forEach(it => inputs += row(it.name + " (expense)", describeItem(it)));

  let out = row("Success rate", pctStr(H.successRate, 1));
  out += row("Tested against", H.total + " periods since " + H.first);
  out += row("Survived", H.survived + " of " + H.total);
  out += row("Median ending balance", money(H.medianEnd));
  out += row("Worst case", money(H.worstEnd));
  out += row("Best case", money(H.bestEnd));

  // Spending behavior over the example period \u2014 the part a single ending
  // balance can't tell you.
  const real = show.rows.map(r => r.realSpend != null ? r.realSpend : r.realWithdrawal);
  const sortedReal = real.slice().sort((a,b) => a-b);
  const highSpend = sortedReal[sortedReal.length-1], lowSpend = sortedReal[0];
  let cuts = 0, maxCut = 0;
  for (let i = 1; i < real.length; i++){
    const chg = real[i] - real[i-1];
    if (chg < -0.5){ cuts++; if (-chg > maxCut) maxCut = -chg; }
  }
  let spend = row("Highest year's spending", money(highSpend));
  spend += row("Lowest year's spending", money(lowSpend));
  spend += row("Years spending was cut", cuts + " of " + real.length);
  if (maxCut > 0) spend += row("Biggest single-year cut", "\u2212" + money(maxCut));
  spend += row("Total spent, example period", money(real.reduce((a,v)=>a+v,0)));

  const src = $("chartDD");
  let chart = "";
  if (src && src.childNodes.length){
    const clone = src.cloneNode(true);
    lighten(clone); clone.removeAttribute("style");
    chart = "<div class='sh-chart'>" + clone.outerHTML + "</div>";
  }

  // Verdict line, matching the on-screen wording
  let verdict;
  if (H.successRate >= 0.99) verdict = "Survived every historical period, including the Depression, 1970s stagflation, and 2008.";
  else if (H.successRate >= 0.90) verdict = "Survived most historical periods. Failed only when retirement began in " +
    H.failYears.slice(0, 8).join(", ") + (H.failYears.length > 8 ? ", and others" : "") + ".";
  else verdict = "Ran out of money in " + H.failYears.length + " of " + H.total +
    " historical periods. Consider a lower withdrawal rate or a strategy that adjusts spending.";

  // Compact year-by-year for the example period, sampled if long so it never
  // overflows the page \u2014 every year for a plan under ~20 years, every other
  // year beyond that, every 3rd beyond 40.
  const step = show.rows.length <= 20 ? 1 : show.rows.length <= 40 ? 2 : 3;
  const tableRows = show.rows.filter((r, i) => i === 0 || i === show.rows.length - 1 || i % step === 0);
  const sheetHasCustomIncome = (o.incomeItems || []).some(it => it.on !== false);
  let table = "<table><thead><tr><th>" + (ddRetireAge != null ? "Age" : "Year") + "</th><th>Withdrawal</th><th>Soc. Sec.</th>" +
    (sheetHasCustomIncome ? "<th>Other Income</th>" : "") +
    "<th>Return</th><th>End balance</th></tr></thead><tbody>";
  tableRows.forEach(r => {
    table += "<tr><td>" + ddAgeVal(r.year) + "</td><td>" + money(r.withdrawal) + "</td><td>" +
      (r.ss > 0 ? money(r.ss) : "\u2014") + "</td>" +
      (sheetHasCustomIncome ? "<td>" + (r.customIncome > 0 ? money(r.customIncome) : "\u2014") + "</td>" : "") +
      "<td>" + r.ret.toFixed(1) + "%</td><td>" +
      money(r.realEnd) + "</td></tr>";
  });
  table += "</tbody></table>";

  $("sheet").innerHTML =
    "<div class='sh-h'>" + SHEET_MARK + "<h1>Will My Money Last?</h1><span>" + fmtNum(o.years) + " year retirement &middot; tested since " + H.first + "</span></div>" +
    "<div class='sh-big'>" +
      "<div><div class='k'>Success rate</div><div class='v'>" + pctStr(H.successRate, 0) +
        "</div><div class='n'>" + H.survived + " of " + H.total + " periods</div></div>" +
      "<div><div class='k'>Median ending balance</div><div class='v'>" + money(H.medianEnd) +
        "</div><div class='n'>today's dollars</div></div>" +
      "<div><div class='k'>Worst case</div><div class='v'>" + money(H.worstEnd) +
        "</div><div class='n'>today's dollars</div></div>" +
    "</div>" + chart +
    "<div class='sh-cols'>" +
      "<section><div class='sh-t'>Plan</div>" + inputs + "</section>" +
      "<section><div class='sh-t'>Results</div>" + out + "</section>" +
      "<section><div class='sh-t'>Spending, retiring " + showLabel + "</div>" + spend + "</section>" +
    "</div>" +
    "<div class='sh-table'><div class='sh-t'>Year by year &middot; retiring in " + showLabel +
      (show.depleted ? (" (ran out " + (ddRetireAge != null ? "at age " + ddAgeVal(show.depletedYear) : "in year " + show.depletedYear) + ")") : " (survived)") + "</div>" + table + "</div>" +
    "<div class='sh-foot'>" + verdict + " Tested against real US market history (" +
      H.first + "\u2013" + (HIST_START + HIST_STOCK.length - 1) + "). " +
    "Surviving every period is evidence a plan is reasonable, not a guarantee. Not financial advice.</div>";
}

function buildBudgetSheet(){
  const incFreq = bgIncomeFreq;
  const incomeYr = num("bgIncomeIn") * incFreq;
  const spentYr = budget.reduce((a, r) => a + (isSavingsRow(r) ? 0 : annualize(r)), 0);
  const savedYr = budget.reduce((a, r) => a + (isSavingsRow(r) ? annualize(r) : 0), 0);
  const leftYr = incomeYr - spentYr - savedYr;
  if (!(incomeYr > 0) && !(spentYr > 0)){ $("sheet").innerHTML = ""; toast("Add your income first"); return false; }

  // Group spending by its preset category, in the same order the budget tool
  // itself uses, so the sheet reads like the tool rather than an arbitrary list.
  const order = ["Housing", "Transportation", "Health", "Food", "Lifestyle", "Saving & debt", "Custom"];
  const groups = {};
  budget.forEach(r => {
    if (annualize(r) <= 0 || isSavingsRow(r)) return;
    const g = r.group || "Custom";
    (groups[g] = groups[g] || []).push(r);
  });
  let spendCols = "";
  order.filter(g => groups[g]).forEach(g => {
    let section = "<section style='flex:1;min-width:0'><div class='sh-t'>" + g + "</div>";
    groups[g].forEach(r => { section += row(r.desc, money(annualize(r) / 12) + "/mo"); });
    section += "</section>";
    spendCols += section;
  });

  let saveRows = "";
  budget.filter(r => isSavingsRow(r) && annualize(r) > 0).forEach(r => {
    saveRows += row(r.desc, money(annualize(r) / 12) + "/mo");
  });

  let summary = row("Income", money(incomeYr / 12) + "/mo");
  summary += row("Spending", money(spentYr / 12) + "/mo");
  if (savedYr > 0) summary += row("Saving", money(savedYr / 12) + "/mo");
  summary += row("Left over", money(leftYr / 12) + "/mo");
  summary += row("Percent of income spent", incomeYr ? pctStr(spentYr / incomeYr, 0) : "\u2014");
  if (savedYr > 0) summary += row("Percent of income saved", incomeYr ? pctStr(savedYr / incomeYr, 0) : "\u2014");

  const efMonths = Math.max(1, Math.round(num("efMonths")) || 6);
  const efTarget = (spentYr / 12) * efMonths;

  $("sheet").innerHTML =
    "<div class='sh-h'>" + SHEET_MARK + "<h1>Monthly Budget</h1><span>Per month, unless noted</span></div>" +
    "<div class='sh-big'>" +
      "<div><div class='k'>Income</div><div class='v'>" + money(incomeYr / 12) +
        "</div><div class='n'>per month</div></div>" +
      "<div><div class='k'>Spending + saving</div><div class='v'>" + money((spentYr + savedYr) / 12) +
        "</div><div class='n'>per month</div></div>" +
      "<div><div class='k'>Left over</div><div class='v'>" + money(leftYr / 12) +
        "</div><div class='n'>" + (incomeYr ? pctStr(leftYr / incomeYr, 0) : "\u2014") + " of income</div></div>" +
    "</div>" +
    "<div class='sh-cols'>" +
      "<section style='flex:1;min-width:0'><div class='sh-t'>Summary</div>" + summary +
        (saveRows ? "<div class='sh-t' style='margin-top:8px'>Saving</div>" + saveRows : "") +
      "</section>" +
      "<section style='flex:1;min-width:0'><div class='sh-t'>Emergency fund</div>" +
        row(efMonths + "-month target", money(efTarget)) +
        row("Based on", money(spentYr / 12) + "/mo actual expenses") +
      "</section>" +
    "</div>" +
    "<div class='sh-cols'>" + spendCols + "</div>" +
    "<div class='sh-foot'>A snapshot of what you entered. Savings and retirement contributions " +
    "are shown separately from spending and excluded from the emergency fund target. " +
    "Doesn't include taxes withheld or account for irregular income.</div>";
}

function buildBasicSheet(){
  const p = readBasic();
  if (!(p.years > 0)){ $("sheet").innerHTML = ""; return; }
  const R = projectBasic(p);
  const rows = R.years.map(y => ({year:y.year, end:y.end, growth:y.growth,
                                  contrib:y.contrib}));
  const cross = rows.find(r => r.growth > r.contrib && r.contrib > 0);
  let ms = row("Crossover year", cross ? "Age " + fmtNum(p.age + cross.year) : "\u2014");
  MS_LADDER.filter(v => v <= R.fv).slice(-4).forEach(v => {
    const hit = rows.find(r => r.end >= v);
    ms += row("Reaches " + money(v), hit ? "Age " + fmtNum(p.age + hit.year) : "\u2014");
  });
  const level = RISK_LEVELS.find(r => Math.abs(r.real - p.real) < 1e-9);
  let inputs = row("Age today", fmtNum(p.age));
  inputs += row("Retiring at", fmtNum(p.retire));
  inputs += row("Saved so far", money(p.initial));
  inputs += row("Contributing", money(p.contrib, 2) + " " + PERIOD_ADV[p.period]);
  inputs += row("Invested as", level ? level.label : pctStr(p.real, 2));
  inputs += row("Growth after inflation", pctStr(p.real, 2));
  let out = row("You put in", money(R.contribTotal));
  out += row("Growth added", money(R.growth));
  out += row("Value at retirement", money(R.fv));
  out += row("Income per year", money(R.fv * .04));
  out += row("Income per month", money(R.fv * .04 / 12));

  const src = $("chartQ");
  let chart = "";
  if (src && src.childNodes.length){
    const clone = src.cloneNode(true);
    lighten(clone); clone.removeAttribute("style");
    chart = "<div class='sh-chart'>" + clone.outerHTML + "</div>";
  }

  // Compact year-by-year, using age rather than plan-year to match how Basic
  // presents everything else.
  const step = rows.length <= 15 ? 1 : rows.length <= 30 ? 2 : 3;
  const tableRows = rows.filter((r, i) => i === 0 || i === rows.length - 1 || i % step === 0);
  let table = "<table><thead><tr><th>Age</th><th>Contributed</th><th>Growth</th>" +
    "<th>Balance</th></tr></thead><tbody>";
  tableRows.forEach(r => {
    table += "<tr><td>" + (p.age + r.year) + "</td><td>" + money(r.contrib) + "</td><td>" +
      money(r.growth) + "</td><td>" + money(r.end) + "</td></tr>";
  });
  table += "</tbody></table>";

  $("sheet").innerHTML =
    "<div class='sh-h'>" + SHEET_MARK + "<h1>Retirement Projection</h1><span>" +
      fmtYears(p.years) + " of saving &middot; every figure in today's dollars</span></div>" +
    "<div class='sh-big'>" +
      "<div><div class='k'>Value at retirement</div><div class='v'>" + money(R.fv) +
        "</div><div class='n'>at age " + fmtNum(p.retire) + "</div></div>" +
      "<div><div class='k'>Income per year</div><div class='v'>" + money(R.fv * .04) +
        "</div><div class='n'>taking 4% a year</div></div>" +
      "<div><div class='k'>Income per month</div><div class='v'>" + money(R.fv * .04 / 12) +
        "</div><div class='n'>before any tax</div></div>" +
    "</div>" + chart +
    "<div class='sh-cols'>" +
      "<section><div class='sh-t'>Your answers</div>" + inputs + "</section>" +
      "<section><div class='sh-t'>Results</div>" + out + "</section>" +
      "<section><div class='sh-t'>Milestones</div>" + ms + "</section>" +
    "</div>" +
    "<div class='sh-table'><div class='sh-t'>Year by year</div>" + table + "</div>" +
    "<div class='sh-foot'>All figures are in today's dollars and assume a steady " +
    "return after inflation, no tax and no fees. Real returns vary year to year. " +
    "Projections are not predictions, and this is not financial advice.</div>";
}
function doSummary(){
  if (buildSheet() === false) return;
  setTimeout(() => window.print(), 60);
}

/* ---------- income tax tool ---------- */
const TAX_COLORS = {fed:"#e2795f", state:"#e9b872", fica:"#7d9fd6", net:"#4fbf95"};
$("txState").innerHTML = Object.keys(STATES)
  .sort((a,b) => STATES[a].n.localeCompare(STATES[b].n))
  .map(k => "<option value='" + k + "'>" + STATES[k].n + "</option>").join("");

$("rcState").innerHTML = $("txState").innerHTML;
$("brState").innerHTML = $("txState").innerHTML;
{ const o = $("brState").querySelector("option[value='IL']");
  if (o){ o.defaultSelected = true; $("brState").value = "IL"; } }
acFillStates();

let txMode = "normal";
const BKT_COLORS = {trad:"#e2795f", roth:"#4fbf95", brok:"#7d9fd6",
                    ss:"#e9b872", pension:"#c98fb8", other:"#a98fd6"};
const LTCG_COLORS = ["#4fbf95", "#e9b872", "#e2795f"];   // 0%, 15%, 20%

let txActiveParts = [], txPieDefaultLabel = "All taxes", txPieDefaultVal = "";
let _txDeactivateTimer = null;

(function(){
  function txActivate(idx){
    clearTimeout(_txDeactivateTimer);
    $("txPie").querySelectorAll("circle[data-idx]").forEach(function(c){
      c.style.opacity = +c.dataset.idx === idx ? "" : "0.18";
    });
    $("txBars").querySelectorAll(".bar[data-idx]").forEach(function(b){
      b.style.opacity = +b.dataset.idx === idx ? "" : "0.25";
    });
    var pt = txActiveParts[idx];
    var lbl = $("txPieLbl"), val = $("txPieVal");
    if (pt && lbl && val){ lbl.textContent = pt.label || ""; val.textContent = money(pt.v); }
  }
  function txDeactivate(){
    _txDeactivateTimer = setTimeout(function(){
      $("txPie").querySelectorAll("circle[data-idx]").forEach(function(c){ c.style.opacity = ""; });
      $("txBars").querySelectorAll(".bar[data-idx]").forEach(function(b){ b.style.opacity = ""; });
      var lbl = $("txPieLbl"), val = $("txPieVal");
      if (lbl) lbl.textContent = txPieDefaultLabel;
      if (val) val.textContent = txPieDefaultVal;
    }, 60);
  }
  var pie = $("txPie");
  pie.addEventListener("mouseover", function(e){
    var c = e.target.closest ? e.target.closest("circle[data-idx]") : null;
    if (c) txActivate(+c.dataset.idx); else txDeactivate();
  });
  pie.addEventListener("mouseleave", txDeactivate);
  var barsEl = $("txBars");
  barsEl.addEventListener("mouseover", function(e){
    var b = e.target.closest ? e.target.closest(".bar[data-idx]") : null;
    if (b) txActivate(+b.dataset.idx);
  });
  barsEl.addEventListener("mouseleave", txDeactivate);
})();

function readTax(){
  const status = $("txStatus").value;
  const seniors = Math.min(status === "m" ? 2 : 1, parseInt($("txSeniors").value, 10) || 0);
  const trad = num("txTrad"), roth = num("txRoth"), brok = num("txBrok"),
        ss = num("txSS"), pension = num("txPension"), other = num("txOther");
  // Spouse's income only exists as a separate concept in Normal Income mode,
  // where FICA's per-earner wage cap makes the split matter. Retirement mode
  // has no FICA, so its withdrawals stay combined into one household total.
  const gross2 = (txMode === "normal" && status === "m") ? num("txGross2") : 0;
  return {mode:txMode,
          gross: txMode === "retire"
            ? trad + roth + brok + ss + pension + other : num("txGross"),
          gross2,
          trad, roth, brok, ss, pension, other,
          penPublic: $("txPenType").value === "pub",
          gainPct:num("txGainPct") / 100, seniors,
          status, state:$("txState").value,
          pre:num("txPre"), dedType:$("txDedType").value, item:num("txItem")};
}
/* One entry point, so everything downstream — the summary sheet, the share
   card, the budget's "copy from tax" button — keeps working without caring
   which mode the tool is in. Both branches return the same core keys. */
function runTax(inp){
  return inp.mode === "retire" ? computeRetireTax(inp) : computeTax(inp);
}
function bar(label, value, share, color, idx){
  return "<div class='bar'" + (idx !== undefined ? " data-idx='" + idx + "'" : "") +
    "><div class='lbl'><span>" + label + "</span><b>" +
    money(value) + "</b></div><div class='track'><div class='fill' style='width:" +
    (Math.max(0, Math.min(1, share)) * 100).toFixed(1) + "%;background:" + color +
    "'></div></div></div>";
}
function donut(parts){
  const R = 100, C = 110, sw = 30, circ = 2 * Math.PI * (R - sw / 2);
  const tot = parts.reduce((a, x) => a + x.v, 0) || 1;
  let off = 0, out = "";
  parts.forEach((pt, i) => {
    const frac = pt.v / tot;
    if (frac <= 0) return;
    out += "<circle cx='" + C + "' cy='" + C + "' r='" + (R - sw / 2) +
      "' fill='none' stroke='" + pt.c + "' stroke-width='" + sw +
      "' stroke-dasharray='" + (frac * circ).toFixed(2) + " " + circ.toFixed(2) +
      "' stroke-dashoffset='" + (-off * circ).toFixed(2) +
      "' transform='rotate(-90 " + C + " " + C + ")'" +
      " data-idx='" + i + "' style='transition:opacity .15s;cursor:pointer'></circle>";
    off += frac;
  });
  return out;
}
/* One bar per income source. The track length is that bucket's withdrawal set
   against the largest bucket, so you can see the relative size of each pot;
   the filled part is the share of it that went to tax. */
function bucketBar(b, maxAmt, color){
  const trackPct = maxAmt > 0 ? (b.withdrawn / maxAmt) * 100 : 0;
  const fillPct = b.withdrawn > 0 ? (b.tax / b.withdrawn) * 100 : 0;
  return "<div class='bar'><div class='lbl'><span>" + b.label + "</span><b>" +
    money(b.withdrawn) + (b.withdrawn > 0
      ? " \u00b7 " + money(b.tax) + " tax (" + pctStr(b.eff, 1) + ")" : "") +
    "</b></div><div class='track' style='width:" + Math.max(trackPct, 1.5).toFixed(1) +
    "%'><div class='fill' style='width:" + Math.min(100, fillPct).toFixed(1) +
    "%;background:" + color + "'></div></div></div>";
}

/* The stacking chart. Ordinary taxable income fills the ordinary brackets
   first and then acts as the floor for the gain, so where the gain lands
   depends entirely on how much ordinary income sits underneath it. Drawing
   both on one axis against the 0/15/20% breakpoints is the whole point. */
function txStackChart(R){
  const W = 720, H = 150, padL = 6, padR = 6, iw = W - padL - padR;
  const c0 = R.ltcgCut[0], c15 = R.ltcgCut[1];
  const lo = R.ordTaxable, hi = lo + R.gainTaxable;
  let max = Math.max(hi * 1.12, c0 * 1.14, 1);
  if (hi > c15) max = hi * 1.06;
  const x = v => padL + Math.max(0, Math.min(1, v / max)) * iw;
  const dim = cssVar("--dim"), dimmer = cssVar("--dimmer"),
        text = cssVar("--text"), sans = cssVar("--sans"), mono = cssVar("--mono");
  const barY = 44, barH = 40;
  let s = "";

  // faint zones behind the bar, so the bands read as territory
  const zone = (a, b, fill) => {
    if (b <= a) return "";
    return "<rect x='" + x(a).toFixed(1) + "' y='" + barY + "' width='" +
      (x(b) - x(a)).toFixed(1) + "' height='" + barH + "' fill='" + fill + "'/>";
  };
  s += zone(0, Math.min(max, c0), "rgba(79,191,149,.09)");
  s += zone(Math.min(max, c0), Math.min(max, c15), "rgba(233,184,114,.09)");
  s += zone(Math.min(max, c15), max, "rgba(226,121,95,.09)");

  // ordinary income floor
  if (lo > 0)
    s += "<rect x='" + x(0).toFixed(1) + "' y='" + barY + "' width='" +
      (x(lo) - x(0)).toFixed(1) + "' height='" + barH +
      "' fill='#8ba0ac' opacity='.85' rx='2'/>";

  // the gain, segment by segment
  let cur = lo;
  R.ltcgBands.forEach((b, i) => {
    if (!(b.amount > 0)) return;
    s += "<rect x='" + x(cur).toFixed(1) + "' y='" + barY + "' width='" +
      Math.max(1, x(cur + b.amount) - x(cur)).toFixed(1) + "' height='" + barH +
      "' fill='" + LTCG_COLORS[i] + "' rx='2'/>";
    cur += b.amount;
  });

  // breakpoint markers
  const mark = (v, label) => {
    if (v >= max) return "";
    const px = x(v);
    return "<line x1='" + px.toFixed(1) + "' y1='" + (barY - 12) + "' x2='" +
      px.toFixed(1) + "' y2='" + (barY + barH + 8) +
      "' stroke='" + dim + "' stroke-width='1' stroke-dasharray='3 3'/>" +
      "<text x='" + Math.min(px + 6, W - 130).toFixed(1) + "' y='" + (barY - 18) +
      "' font-size='11.5' fill='" + dim + "' font-family='" + sans + "'>" + label +
      " <tspan font-family='" + mono + "' fill='" + text + "'>" + money(v) + "</tspan></text>";
  };
  s += mark(c0, "0% ends at");
  s += mark(c15, "20% starts at");

  // The two edges of the stack, called out underneath. Both have to stay
  // inside the viewBox and off each other: near the right edge the label flips
  // to end-anchored, and when the two edges are close the second one drops to
  // its own row rather than colliding.
  const xLo = x(lo), xHi = x(hi);
  const row1 = barY + barH + 26, row2 = barY + barH + 44;
  const foot = (px, label, anchor, y) =>
    "<text x='" + Math.max(3, Math.min(px, W - 3)).toFixed(1) + "' y='" + y +
    "' font-size='11.5' text-anchor='" + anchor + "' fill='" + dimmer +
    "' font-family='" + sans + "'>" + label + "</text>";
  const est = txt => txt.length * 6.0;          // rough width at 11.5px
  if (lo > 0 && hi > lo){
    const lbl1 = "ordinary income ends " + money(lo);
    const lbl2 = "gain ends " + money(hi);
    const a2 = xHi + est(lbl2) > W - 4 ? "end" : "start";
    const left2 = a2 === "end" ? xHi - est(lbl2) : xHi;
    const collides = left2 < xLo + 6;
    s += foot(xLo, lbl1, xLo - est(lbl1) < 4 ? "start" : "end", row1);
    s += foot(xHi, lbl2, a2, collides ? row2 : row1);
  } else if (lo > 0){
    s += foot(xLo, "ordinary income ends " + money(lo), "middle", row1);
  } else if (hi > 0){
    const lbl = "gain ends " + money(hi);
    s += foot(xHi, lbl, xHi + est(lbl) > W - 4 ? "end" : "start", row1);
  }

  return s;
}

function renderTax(){
  const inp = readTax();
  const ret = inp.mode === "retire";
  $("txItemWrap").hidden = inp.dedType !== "item";
  const R = runTax(inp);
  return ret ? renderRetireTax(inp, R) : renderNormalTax(inp, R);
}

function renderNormalTax(inp, R){
  $("txStdLabel").textContent = "Standard deduction";
  $("txStdShow").textContent = money(FED_STD[inp.status]);
  $("txSSRow").hidden = true;
  $("txTaxable").textContent = money(R.fedTaxable);
  $("txMarginal").textContent = pctStr(R.marginal, 0);
  if (!$("txGrossTotalWrap").hidden) $("txGrossTotalShow").textContent = money(R.gross);

  // Net pay = gross minus taxes; take-home also subtracts pre-tax savings, which
  // is money you keep but never see in the paycheck.
  const netPay = R.gross - R.total;
  const shown = txView === "take" ? R.net : netPay;
  $("txNetLabel").textContent = txView === "take" ? "Take-home pay" : "Net pay";
  $("txNetNote").textContent = R.gross > 0
    ? (txView === "take"
        ? pctStr(R.gross ? R.net / R.gross : 0, 1) + " of gross, after pre-tax savings"
        : pctStr(R.gross ? netPay / R.gross : 0, 1) + " of gross, after taxes")
    : "Enter your income to begin";
  $("txMonthNote").textContent = txView === "take"
    ? "In your paycheck, after pre-tax savings" : "After all taxes";
  $("txThirdLabel").textContent = "Every two weeks";
  $("txThirdNote").textContent = "26 paychecks a year";
  setBig("txNet", money(shown));
  setBig("txMonth", money(shown / 12));
  setBig("txBiweek", money(shown / 26));
  $("txZeroRoomRow").hidden = true;
  if (R.gross > 0){
    const br = bracketRoom(R.fedTaxable, inp.status);
    $("txRoomLabel").textContent = br ? "Room before " + pctStr(br.nextRate, 0) : "Room before next bracket";
    $("txRoomShow").textContent = br ? money(br.room) : "Top bracket";
  } else {
    $("txRoomLabel").textContent = "Room before next bracket";
    $("txRoomShow").textContent = "\u2014";
  }

  $("txBars").innerHTML =
    bar("Take-home pay", R.net, R.effNet, TAX_COLORS.net, 0) +
    bar("Federal income tax", R.federal, R.effFed, TAX_COLORS.fed, 1) +
    bar("State income tax" + (R.stateNone ? " (none)" : ""), R.state, R.effState, TAX_COLORS.state, 2) +
    bar("FICA (Social Security + Medicare)", R.fica, R.effFica, TAX_COLORS.fica, 3) +
    (R.pre > 0 ? bar("Pre-tax savings", R.pre, R.gross ? R.pre / R.gross : 0, "#8ba0ac", 4) : "");

  const parts = [{v:R.net, c:TAX_COLORS.net, label:"Take-home pay"},
                 {v:R.federal, c:TAX_COLORS.fed, label:"Federal tax"},
                 {v:R.state, c:TAX_COLORS.state, label:"State tax"},
                 {v:R.fica, c:TAX_COLORS.fica, label:"FICA"}];
  if (R.pre > 0) parts.push({v:R.pre, c:"#8ba0ac", label:"Pre-tax savings"});
  txDonut(R, parts);

  // The Social Security wage cap applies per earner, so a joint return splits
  // the line in two rather than showing one household figure that would imply
  // a single shared cap.
  const ssRows = inp.status === "m"
    ? txRow("Your Social Security", R.ss1, R.gross ? R.ss1 / R.gross : 0, TAX_COLORS.fica) +
      txRow("Spouse's Social Security", R.ss2, R.gross ? R.ss2 / R.gross : 0, TAX_COLORS.fica)
    : txRow("Social Security", R.ss, R.gross ? R.ss / R.gross : 0, TAX_COLORS.fica);
  $("txTable").querySelector("tbody").innerHTML =
    txRow("Federal income tax", R.federal, R.effFed, TAX_COLORS.fed) +
    txRow("State income tax" + (R.stateName ? " \u00b7 " + R.stateName : ""), R.state, R.effState, TAX_COLORS.state) +
    ssRows +
    txRow("Medicare" + (R.addl > 0 ? " (incl. surtax)" : ""), R.med + R.addl,
         R.gross ? (R.med + R.addl) / R.gross : 0, TAX_COLORS.fica) +
    "<tr style='font-weight:600'><td>All taxes</td><td>" + money(R.total) + "</td><td>" +
      pctStr(R.effTotal, 2) + "</td><td></td></tr>" +
    "<tr><td>Take-home pay</td><td>" + money(R.net) + "</td><td>" +
      pctStr(R.effNet, 2) + "</td><td></td></tr>" +
    (R.pre > 0 ? "<tr><td>Pre-tax deductions</td><td>" + money(R.pre) + "</td><td>" +
      pctStr(R.gross ? R.pre / R.gross : 0, 2) + "</td><td></td></tr>" : "") +
    "<tr style='font-weight:600;border-top:2px solid var(--line)'><td>Gross pay</td><td>" +
      money(R.gross) + "</td><td>100.00%</td><td></td></tr>";

  txBracketTable(R);
}

function renderRetireTax(inp, R){
  $("txRetGross").textContent = money(R.gross);

  const dedLabel = inp.dedType === "item" ? "Itemized deduction" :
    (R.seniors > 0 ? "Standard deduction, incl. 65+" : "Standard deduction");
  $("txStdLabel").textContent = dedLabel;
  $("txStdShow").textContent = money(R.fedDed);
  $("txSSRow").hidden = !(R.ssGross > 0);
  $("txSSShow").textContent = R.ssGross > 0
    ? money(R.taxableSS) + " (" + pctStr(R.taxableSS / R.ssGross, 0) + ")" : "\u2014";
  $("txTaxable").textContent = money(R.fedTaxable);
  $("txMarginal").textContent = pctStr(R.marginal, 1);

  $("txNetLabel").textContent = "Income after tax";
  $("txNetNote").textContent = R.gross > 0
    ? pctStr(R.effNet, 1) + " of what you withdrew"
    : "Enter your withdrawals to begin";
  $("txMonthNote").textContent = "After all taxes";
  $("txThirdLabel").textContent = "Effective tax rate";
  $("txThirdNote").textContent = R.gross > 0
    ? "Marginal on the next dollar: " + pctStr(R.marginal, 1) : "";
  setBig("txNet", money(R.net));
  setBig("txMonth", money(R.net / 12));
  setBig("txBiweek", pctStr(R.effTotal, 2));
  if (R.gross > 0){
    const br = bracketRoom(R.ordTaxable, inp.status);
    $("txRoomLabel").textContent = br ? "Room before " + pctStr(br.nextRate, 0) : "Room before next bracket";
    $("txRoomShow").textContent = br ? money(br.room) : "Top bracket";
    $("txZeroRoomRow").hidden = false;
    $("txZeroRoomShow").textContent = R.zeroRoom > 0 ? money(R.zeroRoom) : "None left";
  } else {
    $("txRoomLabel").textContent = "Room before next bracket";
    $("txRoomShow").textContent = "\u2014";
    $("txZeroRoomRow").hidden = true;
  }

  $("txBars").innerHTML =
    bar("Income after tax", R.net, R.effNet, TAX_COLORS.net, 0) +
    bar("Federal ordinary income tax", R.fedOrdinary, R.gross ? R.fedOrdinary / R.gross : 0, TAX_COLORS.fed, 1) +
    bar("Federal long-term capital gain tax", R.ltcg, R.gross ? R.ltcg / R.gross : 0, LTCG_COLORS[1], 2) +
    (R.niit > 0 ? bar("Net investment income tax (3.8%)", R.niit, R.gross ? R.niit / R.gross : 0, "#a98fd6", 3) : "") +
    bar("State income tax" + (R.stateNone ? " (none)" : ""), R.state, R.effState, TAX_COLORS.state, 4) +
    (R.pre > 0 ? bar("Pre-tax deductions", R.pre, R.gross ? R.pre / R.gross : 0, "#8ba0ac", 5) : "");

  const parts = [{v:R.net, c:TAX_COLORS.net, label:"Income after tax"},
                 {v:R.fedOrdinary, c:TAX_COLORS.fed, label:"Federal ordinary tax"},
                 {v:R.ltcg, c:LTCG_COLORS[1], label:"Capital gain tax"},
                 {v:R.niit, c:"#a98fd6", label:"Net investment tax"},
                 {v:R.state, c:TAX_COLORS.state, label:"State tax"}];
  if (R.pre > 0) parts.push({v:R.pre, c:"#8ba0ac", label:"Pre-tax deductions"});
  txDonut(R, parts);

  $("txTable").querySelector("tbody").innerHTML =
    txRow("Federal tax on ordinary income", R.fedOrdinary, R.gross ? R.fedOrdinary / R.gross : 0, TAX_COLORS.fed) +
    txRow("Federal tax on long-term gains", R.ltcg, R.gross ? R.ltcg / R.gross : 0, LTCG_COLORS[1]) +
    (R.niit > 0 ? txRow("Net investment income tax", R.niit, R.gross ? R.niit / R.gross : 0, "#a98fd6") : "") +
    txRow("State income tax" + (R.stateName ? " \u00b7 " + R.stateName : ""), R.state, R.effState, TAX_COLORS.state) +
    "<tr style='font-weight:600'><td>All taxes</td><td>" + money(R.total) + "</td><td>" +
      pctStr(R.effTotal, 2) + "</td><td></td></tr>" +
    "<tr><td>Income after tax</td><td>" + money(R.net) + "</td><td>" +
      pctStr(R.effNet, 2) + "</td><td></td></tr>" +
    (R.pre > 0 ? "<tr><td>Pre-tax deductions</td><td>" + money(R.pre) + "</td><td>" +
      pctStr(R.gross ? R.pre / R.gross : 0, 2) + "</td><td></td></tr>" : "") +
    "<tr style='font-weight:600;border-top:2px solid var(--line)'><td>Gross withdrawals</td><td>" +
      money(R.gross) + "</td><td>100.00%</td><td></td></tr>";

  txBracketTable(R);

  // --- per-bucket panel ---
  const keys = ["trad", "roth", "brok", "ss", "pension", "other"];
  const live = R.buckets.map((b, i) => ({b, c:BKT_COLORS[keys[i]]}))
                        .filter(o => o.b.withdrawn > 0);
  const maxAmt = live.reduce((a, o) => Math.max(a, o.b.withdrawn), 0);
  $("txBucketBars").innerHTML = live.length
    ? live.map(o => bucketBar(o.b, maxAmt, o.c)).join("")
    : "<div class='hint'>Enter a withdrawal above to see how it is taxed.</div>";
  $("txBucketTable").querySelector("tbody").innerHTML =
    live.map(o => "<tr><td><span style='color:" + o.c + "'>\u25a0</span> " + o.b.label +
      "</td><td>" + money(o.b.withdrawn) + "</td><td>" + money(o.b.taxable) +
      "</td><td>" + money(o.b.federal) + "</td><td>" + money(o.b.state) +
      "</td><td>" + money(o.b.tax) + "</td><td>" + pctStr(o.b.eff, 1) + "</td></tr>").join("") +
    "<tr style='font-weight:600;border-top:2px solid var(--line)'><td>All sources</td><td>" +
      money(R.gross) + "</td><td>" +
      money(live.reduce((a, o) => a + o.b.taxable, 0)) + "</td><td>" +
      money(R.federal) + "</td><td>" + money(R.state) + "</td><td>" + money(R.total) +
      "</td><td>" + pctStr(R.effTotal, 1) + "</td></tr>";

  let note = "The Roth column is zero by construction, and only the gain portion of " +
    "the brokerage withdrawal is taxable; the rest is your own basis coming back. " +
    "Ordinary tax is split across the traditional, Social Security and other-income " +
    "rows in proportion to what each contributed to ordinary taxable income.";
  if (R.ssGross > 0){
    note += " Your provisional income is " + money(R.provisional) + ", which puts " +
      (R.ssTier === 0 ? "none of your benefits in the tax base."
       : "up to " + R.ssTier + "% of your benefits in the tax base: " +
         money(R.taxableSS) + " of " + money(R.ssGross) + ".");
  }
  if (R.stateNote){
    note += " <b>" + (R.stateName || "This state") + ".</b> " + R.stateNote;
    if (R.stateExcluded > 0)
      note += " That removed " + money(R.stateExcluded) + " from the state tax base here.";
  }
  $("txBucketNote").innerHTML = note;

  // --- capital gain stacking panel ---
  const hasGain = R.gain > 0;
  $("txGainPanel").hidden = !hasGain;
  if (hasGain){
    $("txStack").innerHTML = txStackChart(R);
    const chip = (c, label, v) => "<span><i style='background:" + c + "'></i>" +
      label + " <b>" + v + "</b></span>";
    let leg = chip("#8ba0ac", "Ordinary taxable income", money(R.ordTaxable));
    R.ltcgBands.forEach((b, i) => {
      if (b.amount > 0)
        leg += chip(LTCG_COLORS[i], "Gain taxed at " + pctStr(b.rate, 0), money(b.amount));
    });
    $("txStackLegend").innerHTML = leg;

    let g = "You realized " + money(R.gain) + " of long-term gain on a " +
      money(R.brok) + " brokerage withdrawal; " + money(R.basis) +
      " of that was basis and never touched the return. ";
    g += R.gainTaxable > 0
      ? "The gain sits on top of " + money(R.ordTaxable) +
        " of ordinary taxable income, so it is taxed at a blended <b>" +
        pctStr(R.ltcgRate, 1) + "</b>, costing " + money(R.ltcg) + ". "
      : "Your deductions cover everything, so none of the gain is taxable at all. ";
    if (R.zeroRoom > 0)
      g += "You have <b>" + money(R.zeroRoom) + "</b> of room left in the 0% band: " +
        "gain harvested up to that point would be federally free.";
    else if (R.ltcgBands[0].amount > 0)
      g += "The 0% band is now full.";
    if (R.niit > 0)
      g += " Your MAGI of " + money(R.agi) + " is above the " +
        money(NIIT.threshold[inp.status]) + " net investment income tax threshold, " +
        "adding " + money(R.niit) + ".";
    $("txGainNote").innerHTML = g;
  }
  $("txBucketPanel").hidden = false;
}

function txDonut(R, parts){
  txActiveParts = parts;
  txPieDefaultVal = pctStr(R.effTotal, 1);
  $("txPie").innerHTML = donut(parts) +
    "<text id='txPieLbl' x='110' y='104' text-anchor='middle' font-size='13' fill='" + cssVar("--dim") +
    "' font-family='" + cssVar("--sans") + "' style='pointer-events:none'>All taxes</text>" +
    "<text id='txPieVal' x='110' y='128' text-anchor='middle' font-size='22' font-weight='600' fill='" +
    cssVar("--text") + "' font-family='" + cssVar("--mono") + "' style='pointer-events:none'>" +
    pctStr(R.effTotal, 1) + "</text>";
}
function txRow(k, v, eff, cls){
  return "<tr><td>" + k + "</td><td>" + money(v) + "</td><td>" + pctStr(eff, 2) +
    "</td><td><span style='color:" + cls + "'>\u25a0</span> " + pctStr(eff, 1) + "</td></tr>";
}
function txBracketTable(R){
  txStateRuleTable();
  $("txBrackets").querySelector("tbody").innerHTML = R.bands.map(b =>
    "<tr" + (b.amount > 0 ? "" : " style='opacity:.4'") + "><td>" + pctStr(b.rate, 0) +
    "</td><td>" + money(b.lo) + (b.hi === Infinity ? " and up" : " \u2013 " + money(b.hi)) +
    "</td><td>" + money(b.amount) + "</td><td>" + money(b.tax) + "</td></tr>").join("");
}

/* ---------- the state rules table ----------
   Everything the two tax modes just did at the state level, said in English.
   The rows are generated from the same STATES and RET_STATE data the
   calculation runs on, so the table cannot drift away from the numbers above
   it. The same six rows show in both modes: someone still working wants to
   know what retirement will cost in the state they are in, and someone
   retired wants to know how ordinary income is treated. */

/* A rate, with trailing zeros trimmed: 4.95%, 5%, 2.5%. */
function rp(r){ return (r * 100).toFixed(2).replace(/\.?0+$/, "") + "%"; }

/* "$3,000 single / $6,000 joint", or "$3,000" when the two are the same. */
function sj(pair){
  return pair[0] === pair[1] ? money(pair[0])
    : money(pair[0]) + " single / " + money(pair[1]) + " joint";
}

/* Row 1: how the state taxes a dollar of ordinary income. */
function ruleOrdinary(code, S, st){
  if (S.none) return "No individual income tax. Wages, pensions, retirement-account " +
    "withdrawals, Social Security and investment income are all untaxed.";
  const b = S.b[st];
  const rates = b.map(x => x[1]);
  const top = rates[rates.length - 1];
  const paid = b.filter(x => x[1] > 0);
  let out;
  if (paid.length === 1){
    out = "Flat " + rp(top) + " on all taxable income";
    out += b[0][1] === 0
      ? ", with a zero-rate band up to " + money(paid[0][0]) + ". " : ". ";
  } else {
    out = b.length + " brackets, " + rp(paid[0][1]) + " to " + rp(top) + ". ";
    if (b[0][1] === 0) out += "The first " + money(paid[0][0]) +
      " of taxable income is taxed at zero. ";
    out += "The top rate starts at " + money(S.b.s[S.b.s.length - 1][0]) +
      " single / " + money(S.b.m[S.b.m.length - 1][0]) + " joint. ";
  }
  const d = [];
  if (S.sd) d.push("standard deduction " + sj(S.sd));
  if (S.pe) d.push("personal exemption " + sj(S.pe));
  if (S.pec) d.push("exemption credit " + sj(S.pec) + " rather than a deduction");
  if (S.sdc) d.push("deduction delivered as a " + sj(S.sdc) + " credit");
  out += d.length ? "Against that: " + d.join(", ") + "."
                  : "No standard deduction or personal exemption.";
  if (S.agiCap) out += " The exemption is lost outright: a cliff, not a " +
    "phase-out, above " + sj(S.agiCap) + " of AGI.";
  return out;
}

/* Row 2: long-term capital gain and other investment income. */
function ruleGain(code, S, R){
  if (S.none) return code === "WA"
    ? "No tax on ordinary capital gain at the individual level, but Washington " +
      "levies a separate 7% excise tax on long-term gains above roughly $270,000 " +
      "a year, with real estate and retirement accounts exempt. That tax is not " +
      "calculated here."
    : "Not taxed.";
  let out = "";
  if (R.cgPct) out = rp(R.cgPct) + " of net long-term gain is excluded from the " +
    "state base; the remainder is taxed at the ordinary rates above. ";
  else if (R.cgFlat) out = sj(R.cgFlat) + " of long-term gain is excluded; the " +
    "remainder is taxed at the ordinary rates above. ";
  else if (R.cgMax) out = "Long-term gain is capped at " + rp(R.cgMax) +
    ", computed as an alternative that can never cost more than ordinary rates. ";
  else if (R.cgB) out = "Long-term gain gets its own reduced schedule: " +
    R.cgB.s.map(x => rp(x[1])).join(" then ") + ", instead of the ordinary rates. ";
  else out = "Taxed at the same ordinary rates as everything else. No preferential " +
    "long-term rate, and no equivalent of the federal 0% band. ";
  out += "Only the gain portion of a brokerage sale is taxed; your basis comes back " +
    "untouched, as federally.";
  return out;
}

/* Row 3: Social Security. */
function ruleSS(code, S, R){
  if (S.none) return "Not taxed.";
  if (!SS_TAX_STATES[code])
    return "Fully exempt. Benefits are subtracted from the state base no matter " +
      "how large they are or what else you earn.";
  let out = "Taxed, on the amount that is taxable federally under \u00a786. ";
  if (R.ssFullAge) out += "Fully exempt once you are 65 or older, which is what " +
    "this assumes when you mark someone 65+.";
  else if (R.ssCredit) out += "A credit then refunds the tax on those benefits, " +
    "withdrawn at " + rp(R.ssCredit.phase) + " of income above " + sj(R.ssCredit.cap) +
    ", so the relief disappears well before the top of the income range.";
  else if (R.ssCap && R.ssPct) out += "Fully exempt below " + sj(R.ssCap) +
    " of AGI; above that, " + rp(R.ssPct) + " of the federally taxable benefit stays " +
    "in the base.";
  else if (R.ssCap && R.ssRange) out += "Fully exempt below " + sj(R.ssCap) +
    " of AGI, phasing back in over the next " + money(R.ssRange) + ".";
  else if (R.ssCap) out += "Fully exempt below " + sj(R.ssCap) + " of AGI and fully " +
    "taxable above it, a cliff, not a phase-out.";
  else out += "No income test and no exemption: the federal taxable amount goes " +
    "straight into the state base.";
  return out;
}

/* Rows 4 and 5: pension income, then traditional 401(k) and IRA withdrawals.
   They are separate rows because roughly a dozen states treat them
   differently, which is the whole reason the tool asks for them separately. */
function rulePension(code, S, R){
  if (S.none) return "Not taxed.";
  const bits = [];
  if (R.penFull) bits.push("Fully exempt, public or private.");
  else if (R.pubFull) bits.push("Government pensions, federal, state and local, " +
    "are fully exempt. Private-employer pensions are taxed at ordinary rates.");
  else bits.push("Taxed at ordinary rates.");
  const ex = exclusionSentence(R, "p");
  if (ex) bits.push(ex);
  return bits.join(" ");
}
function ruleTrad(code, S, R){
  if (S.none) return "Not taxed.";
  const bits = [];
  if (R.tradFull) bits.push("Fully exempt. Qualified plan and IRA distributions " +
    "are outside the state base entirely.");
  else bits.push("Taxed at ordinary rates, the same as a pension would be.");
  if (code === "HI") bits.push("Hawaii's exemption covers only the employer-funded " +
    "share of a plan, so the part of a 401(k) that came from your own deferrals " +
    "stays taxable. This treats the whole balance as your own deferrals, which is " +
    "the conservative reading.");
  if (code === "MD") bits.push("Maryland's pension exclusion specifically does " +
    "not reach IRA distributions.");
  const ex = exclusionSentence(R, "t");
  if (ex) bits.push((R.exSrc === "t" ? "" :
    "It shares one allowance with pension income rather than getting its own. ") + ex);
  return bits.join(" ");
}

/* The shared description of a state's retirement-income exclusion, written
   once and shown on whichever of the two rows it actually applies to. */
function exclusionSentence(R, which){
  if (!R.exAmt) return "";
  const src = R.exSrc || "tp";
  const hits = src === "all" || src === "tp" ? true
             : src === "pub" || src === "p" ? which === "p"
             : which === "t";
  if (!hits) return "";
  const big = R.exAmt[0] >= 1e11;
  let out = big ? "Exempt in full" : "Up to " + sj(R.exAmt) + " is excluded";
  if (R.exPer) out += " per person";
  if (src === "all") out += ", and the same allowance covers interest, dividends, " +
    "rent and capital gain";
  if (src === "pub") out += ", and only for government pensions";
  out += R.exAge ? ", from age 65 as modeled here" : ", at any age";
  out += ".";
  if (R.exLessSS === "gross") out += " The allowance is reduced dollar for dollar " +
    "by the Social Security you receive, so a large benefit can consume it outright.";
  else if (R.exLessSS === "taxable") out += " Taxable Social Security comes out of " +
    "that ceiling first, which exempts benefits in full and leaves whatever is " +
    "left over for the rest.";
  if (R.exCap){
    if (R.exPhase === "nj") out += " Full below " + money(R.exCap[0]) +
      " of income, half to " + money(R.exCap[0] + 25000) + ", a quarter to " +
      money(R.exCap[0] + 50000) + ", nothing above.";
    else if (R.exPhase === "lin") out += " Withdrawn dollar for dollar as AGI " +
      "rises above " + sj(R.exCap) + ", so it is gone by " +
      money(R.exCap[0] + R.exRange) + " single / " +
      money(R.exCap[1] + R.exRange) + " joint.";
    else out += " Lost entirely above " + sj(R.exCap) + " of AGI.";
  }
  return out;
}

/* Row 6: what arrives at 65. */
function ruleSenior(code, S, R){
  if (S.none) return "No income tax, so nothing to give.";
  const bits = [];
  if (R.sdAge) bits.push("Extra deduction of " + sj(R.sdAge) + " per person, " +
    "against income of any kind.");
  if (R.agePh) bits.push("Deduction of " + money(R.agePh.amt) + " per person, " +
    "withdrawn dollar for dollar above " + sj(R.agePh.cap) + " of income, so it is " +
    "gone by " + money(R.agePh.cap[0] + R.agePh.amt) + " single / " +
    money(R.agePh.cap[1] + R.agePh.amt) + " joint.");
  if (R.peAge || S.peAge) bits.push("Extra personal exemption of " +
    money(R.peAge || S.peAge) + " per person.");
  if (R.credAge) bits.push("Credit of " + sj(R.credAge) + " per person" +
    (R.ohRet ? ", plus a retirement income credit of up to $200, both lost above " +
      sj(R.exCap) + " of state income." : "."));
  else if (R.ohRet) bits.push("Retirement income credit of up to $200.");
  if (R.exAge && R.exAmt) bits.push("Reaching 65 is also what unlocks the " +
    "retirement exclusion in the rows above, which is the main thing age buys " +
    "here, rather than a separate senior deduction.");
  if (R.ssFullAge) bits.push("Social Security becomes fully exempt at 65.");
  return bits.length ? bits.join(" ")
    : "Nothing beyond the federal age-65 deductions. The state gives no extra " +
      "deduction, exemption or credit at 65.";
}

/* What is knowingly missing. Two or three real items per state, not a
   disclaimer wall: the point is that you know where to go look. */
const STATE_GAPS = {
  AL:"Municipal occupational taxes of roughly 1% to 2% in Birmingham and other cities. Alabama's standard deduction phases down with income.",
  AZ:"Arizona's small-business alternative return, and the full exemption for military retirement pay.",
  AR:"Arkansas's low-income tax tables, which override the brackets at the bottom of the range.",
  CA:"State disability insurance, 1.2% of all wages with no cap, which functions like a payroll tax on the working side. California's own itemized deduction rules differ from the federal ones.",
  CO:"The $20,000 version of the pension subtraction available from 55 to 64, and TABOR-driven rate reductions that temporarily cut the flat rate in some years.",
  CT:"Connecticut's benefit recapture, which claws back the value of the lower brackets at higher incomes and can add several hundred dollars. Also the personal exemption's own phase-out.",
  DE:"Wilmington's 1.25% city wage tax on earned income.",
  GA:"The $5,000 sublimit on earned income inside the retirement exclusion, and the $35,000 version available from 62 to 64.",
  HI:"Working out how much of a 401(k) was employer-funded, since that share is exempt too. This assumes none of it was, so the real Hawaii bill may be lower.",
  ID:"Idaho's retirement benefits deduction for federal Civil Service, military and public-safety retirees, which is generous where it applies.",
  IL:"Nothing large. Illinois has no local income taxes and its retirement treatment is unusually simple.",
  IN:"County income taxes, which run roughly 1% to 3% on top of the state rate and apply to retirement income too. Indiana's military retirement exemption.",
  IA:"Iowa's retired-farmer and employee-stock-ownership elections, and its inheritance tax.",
  KS:"Kansas's food sales tax credit and homestead property tax refund, both of which matter at lower retirement incomes.",
  KY:"Local occupational license taxes of roughly 1% to 2.5% on earned income in Louisville, Lexington and elsewhere. The full exemption for service credited before 1998.",
  LA:"Parish-level differences and Louisiana's own itemized deduction rules, which depart from the federal ones.",
  ME:"Maine's alternative minimum tax and the phase-out of its personal exemption at higher incomes.",
  MD:"County and Baltimore City income taxes, which run 2.25% to 3.20% on top of the state rate and apply to retirement income. Maryland's senior tax credit of $1,000 to $1,750 below $100,000 / $150,000 of income.",
  MA:"Working out the previously-taxed contribution basis in an IRA, which Massachusetts lets you recover tax-free. The 4% surtax above roughly $1.08 million is in the brackets above.",
  MI:"City income taxes in Detroit, Grand Rapids and about two dozen others, roughly 1% to 2.4%, which reach retirement income.",
  MN:"Minnesota's alternative minimum tax and its separate public-pension subtraction for certain retirees.",
  MS:"The rule that early distributions taken before the plan's retirement age lose the exemption and are taxed in full.",
  MO:"Earnings taxes of 1% in Kansas City and St. Louis. The $6,000 private pension exemption below $25,000 / $32,000 of income.",
  MT:"Montana's capital gain credit interaction with its reduced gain rates, and its elderly homeowner credit.",
  NE:"Nebraska's full exemption for military retirement benefits.",
  NJ:"New Jersey taxes 401(k) contributions going in, so part of every withdrawal is a tax-free return of basis that this does not track; the real New Jersey bill is usually lower than shown. Also the property tax deduction and senior freeze.",
  NM:"The cap on New Mexico's capital gain deduction, which limits the 40% figure at higher gain amounts.",
  NY:"New York City resident tax of roughly 3.1% to 3.9%, and Yonkers's surcharge, both of which reach pension and retirement-account income. New York's supplemental tax recapture at high incomes.",
  NC:"The Bailey exemption for government retirees vested before August 1989, which exempts their pensions entirely.",
  ND:"Nothing large. North Dakota's rates are low enough that the gain exclusion does most of the work.",
  OH:"Municipal income taxes of roughly 1% to 3% and school district income taxes, though most Ohio municipalities exempt retirement income. Ohio's joint filing credit and lump-sum retirement credit.",
  OK:"Oklahoma's full exemption for military retirement and its separate federal Civil Service allowance.",
  OR:"Multnomah County and Portland-area local income taxes, which stack to several percent on higher incomes. Oregon's retirement income credit at low household incomes, and its federal tax subtraction.",
  PA:"Local earned income taxes of roughly 1% to 3.9%, though these fall on wages rather than retirement income. Distributions taken before retirement age lose the exemption.",
  RI:"The requirement that you have actually reached full retirement age, not merely 65, for either the Social Security or pension relief.",
  SC:"South Carolina's separate treatment of military retirement, and its two-wage-earner credit.",
  UT:"Utah's credit phase-out runs on a modified AGI that adds back some untaxed income, so the real credit can be smaller than shown. The $450 retirement credit for taxpayers born before 1953.",
  VT:"Vermont's alternative minimum tax, and the $10,000 exclusion for Civil Service and military retirement.",
  VA:"The rule that the age deduction is unlimited for taxpayers born before 1939, and Virginia's separate military benefits subtraction.",
  WV:"West Virginia's separate full exemptions for state police, teachers' and federal Civil Service retirement, and its senior citizen property tax credit.",
  WI:"The requirement that you are 67, not 65, for the $24,000 exclusion, marking someone 65+ here grants it two years early. Wisconsin's married-couple credit and school property tax credit.",
  DC:"The District's $3,000 exclusion for government pensions at 62, and its own itemized deduction limits.",
  AK:"Nothing. Alaska has no individual income tax and no local income taxes.",
  FL:"Nothing at the income tax level. Florida's tangible and documentary taxes are unrelated.",
  NV:"Nothing. Nevada has no individual income tax.",
  NH:"New Hampshire's interest and dividends tax was fully repealed effective 2025, so there is nothing left to model.",
  SD:"Nothing. South Dakota has no individual income tax.",
  TN:"Nothing. Tennessee's Hall tax on interest and dividends was repealed in 2021.",
  TX:"Nothing. Texas has no individual income tax.",
  WA:"The 7% excise tax on long-term capital gains above roughly $270,000 a year, which is not calculated here. Real estate and retirement accounts are exempt from it.",
  WY:"Nothing. Wyoming has no individual income tax."
};

/* Things true of every state, worth saying once rather than fifty-one times. */
const GAPS_UNIVERSAL = "Everywhere: state credits that phase out on income " +
  "(property tax, renter, low-income and dependent credits), state alternative " +
  "minimum taxes, differences between state and federal itemized deductions, " +
  "part-year and non-resident apportionment, and estate or inheritance taxes.";

function txStateRuleTable(){
  const code = $("txState").value;
  const st = $("txStatus").value;
  const S = STATES[code] || {none:1, n:"None"};
  const R = RET_STATE[code] || {};
  const rows = [
    ["Ordinary income", ruleOrdinary(code, S, st)],
    ["Long-term capital gain", ruleGain(code, S, R)],
    ["Social Security", ruleSS(code, S, R)],
    ["Pension / annuity", rulePension(code, S, R)],
    ["Traditional 401(k) / IRA", ruleTrad(code, S, R)],
    ["Age 65 and over", ruleSenior(code, S, R)]
  ];
  $("txStateRuleName").textContent = S.n || "";
  $("txStateRules").querySelector("tbody").innerHTML = rows.map(r =>
    "<tr><td style='white-space:nowrap;font-weight:600'>" + r[0] + "</td><td>" +
    r[1] + "</td></tr>").join("");
  $("txStateGaps").innerHTML = "<b>Not included in the figures above.</b> " +
    (STATE_GAPS[code] || "") + " " + GAPS_UNIVERSAL;
}

/* Switching modes swaps which inputs are on screen and which output panels
   exist. The Normal Income side is left exactly as it was. */
function applyTaxMode(){
  const ret = txMode === "retire";
  $("segTxMode").querySelectorAll("button").forEach(x =>
    x.classList.toggle("on", x.getAttribute("data-txmode") === txMode));
  $("txGrossWrap").hidden = ret;
  $("txRetSources").hidden = !ret;
  $("txSeniorWrap").hidden = !ret;
  $("segTxView").hidden = ret;
  $("txRetLbl").hidden = !ret;
  $("txBucketPanel").hidden = !ret;
  $("txGainPanel").hidden = true;      // renderRetireTax turns it back on if there is a gain
  $("txPreTip").setAttribute("data-tip", ret ? "txpreret" : "txpre");
  syncSeniorOptions();
  syncGrossFields();
}
/* "Both spouses" only means anything on a joint return. */
function syncSeniorOptions(){
  const joint = $("txStatus").value === "m";
  const opt = $("txSeniors").querySelector("option[value='2']");
  opt.hidden = !joint;
  opt.disabled = !joint;
  $("txSeniors").querySelector("option[value='1']").textContent =
    joint ? "One spouse" : "Yes";
  if (!joint && $("txSeniors").value === "2") $("txSeniors").value = "1";
}
/* A second earner only exists in Normal Income mode on a joint return -- that's
   the only place FICA's per-earner wage cap makes the split matter. Toggling
   in a second grid column (rather than just hiding/showing the field) keeps
   the single-earner case from leaving a blank half-width gap next to it. */
function syncGrossFields(){
  const split = txMode === "normal" && $("txStatus").value === "m";
  $("txGrossWrap").classList.toggle("two", split);
  $("txGrossWrap").classList.toggle("bottomalign", split);
  $("txGross2Wrap").hidden = !split;
  $("txGrossTotalWrap").hidden = !split;
  $("txGrossLabel").textContent = split ? "Your gross income" : "Gross income";
}

let txView = "net";
$("segTxView").addEventListener("click", e => {
  const b = e.target.closest ? e.target.closest("button[data-view]") : null;
  if (!b) return;
  txView = b.getAttribute("data-view");
  $("segTxView").querySelectorAll("button").forEach(x =>
    x.classList.toggle("on", x.getAttribute("data-view") === txView));
  renderTax();
});
$("segTxMode").addEventListener("click", e => {
  const b = e.target.closest ? e.target.closest("button[data-txmode]") : null;
  if (!b) return;
  txMode = b.getAttribute("data-txmode");
  applyTaxMode();
  renderTax();
});
["txGross","txGross2","txPre","txItem","txTrad","txRoth","txBrok","txGainPct","txSS","txPension","txOther"]
  .forEach(id => $(id).addEventListener("input", renderTax));
["txStatus","txState","txDedType","txSeniors","txPenType"].forEach(id =>
  $(id).addEventListener("change", () => { syncSeniorOptions(); syncGrossFields(); renderTax(); }));

/* ---------- mortgage tool ---------- */
let mortPoints = [];
function readMort(){
  const extrasOn = $("moExtrasOn").value === "1";
  return {price:num("moPrice"), down:num("moDownAmt"), rate:rate("moRate"),
          term:parseFloat($("moTerm").value), taxPct:rate("moTax"), ins:num("moIns"),
          pmiPct:rate("moPmi"), hoa:num("moHoa"),
          maintPct:rate("moMaint"), util:num("moUtil"),
          // Zeroed out whenever the panel is collapsed, so toggling it off is
          // the same as never having touched it -- not just hiding the fields.
          extraMonthly: extrasOn ? num("moExtraMo") : 0,
          extraOnce: extrasOn ? num("moExtraOnce") : 0,
          extraOnceMonth: extrasOn ? num("moExtraWhen") : 0,
          recast: extrasOn && $("moRecast").value === "1",
          refiOn: extrasOn && rate("moRefiRate") > 0,
          refiRate: rate("moRefiRate"), refiTerm: parseFloat($("moRefiTerm").value),
          refiCost: num("moRefiCost")};
}
/* PMI only exists below 20% down, so the field mirrors that: it fills in a
   default when PMI applies and blanks to 0 when it doesn't, rather than showing
   a rate that isn't used. */
const PMI_DEFAULT = 0.6;
let pmiAuto = false;
function syncPmi(){
  if (pmiAuto) return;
  pmiAuto = true;
  const price = num("moPrice"), down = num("moDownAmt");
  const ltv = price > 0 ? (price - down) / price : 0;
  const cur = num("moPmi");
  if (ltv > .80 && cur === 0) $("moPmi").value = String(PMI_DEFAULT);
  else if (ltv <= .80 && cur !== 0) $("moPmi").value = "0";
  pmiAuto = false;
}
/* the two down-payment fields mirror each other; whichever was typed in wins */
let downLock = false;
function syncDown(from){
  if (downLock) return;
  downLock = true;
  const price = num("moPrice");
  if (from === "pct"){
    $("moDownAmt").value = groupDigits((price * rate("moDownPct")).toFixed(0), true);
  } else {
    $("moDownPct").value = price > 0
      ? String(Math.round(num("moDownAmt") / price * 10000) / 100) : "0";
  }
  downLock = false;
}
function moWhen(months){
  const y = Math.floor(months / 12), m = months % 12;
  if (!y) return m + (m === 1 ? " month" : " months") + " in";
  if (!m) return "year " + y;
  return "year " + y + ", month " + m;
}
function moDur(months){
  const y = Math.floor(months / 12), m = months % 12;
  if (!y) return m + (m === 1 ? " month" : " months");
  if (!m) return y + (y === 1 ? " year" : " years");
  return y + "y " + m + "m";
}
function renderMortExtras(m, R){
  const active = R.extraActive;
  $("moExtraPanel").hidden = !active && !m.refiOn;
  if (!active){
    $("moExtraStats").innerHTML = "";
  } else {
    const base = mortgage(Object.assign({}, m, {extraMonthly:0, extraOnce:0,
      extraOnceMonth:0, recast:false}));
    const monthsSooner = base.payoffMonth - R.payoffMonth;
    const interestSaved = base.totalInterest - R.totalInterest;
    let html = "";
    html += "<div class='kv'><span class='k'>Payoff</span><span class='v pos'>" +
      moWhen(R.payoffMonth) + (monthsSooner > 0
        ? " (" + moDur(monthsSooner) + " sooner)" : "") + "</span></div>";
    html += "<div class='kv'><span class='k'>Interest saved</span><span class='v pos'>" +
      money(Math.max(0, interestSaved)) + "</span></div>";
    if (R.recastPI != null)
      html += "<div class='kv'><span class='k'>Payment after the recast</span><span class='v'>" +
        money(R.recastPI) + "/mo</span></div>";
    $("moExtraStats").innerHTML = html;
  }

  $("moRefiBlock").hidden = !m.refiOn;
  if (m.refiOn){
    const RF = refiCompare(m, {rate:m.refiRate, term:m.refiTerm, cost:m.refiCost});
    $("moRefiHead").textContent = pctStr(m.refiRate, 2) + " for " + fmtNum(m.refiTerm) + " years";
    let html = "<div class='kv'><span class='k'>New payment</span><span class='v'>" +
      money(RF.then.pi) + "/mo</span></div>";
    html += "<div class='kv'><span class='k'>Monthly change</span><span class='v " +
      (RF.monthlyDelta >= 0 ? "pos" : "neg") + "'>" +
      (RF.monthlyDelta >= 0 ? "\u2212" : "+") + money(Math.abs(RF.monthlyDelta)) + "/mo</span></div>";
    html += "<div class='kv'><span class='k'>Breaks even on closing costs</span><span class='v'>" +
      (RF.breakEvenMonths == null ? "Never \u2014 payment doesn't drop" :
       RF.breakEvenMonths <= 0 ? "Immediately \u2014 no closing costs to recover" :
       moDur(RF.breakEvenMonths)) +
      "</span></div>";
    html += "<div class='kv'><span class='k'>Over the life of the loan</span><span class='v " +
      (RF.lifetimeDelta >= 0 ? "pos" : "neg") + "'>" +
      (RF.lifetimeDelta >= 0 ? "Saves " : "Costs ") + money(Math.abs(RF.lifetimeDelta)) +
      "</span></div>";
    $("moRefiStats").innerHTML = html;
  }
}
function renderMort(){
  const m = readMort();
  const R = mortgage(m);
  $("moLoan").textContent = money(R.loan);
  $("moDownShow").textContent = money(m.down) + " (" + pctStr(m.price ? m.down / m.price : 0, 1) + ")";
  $("moTotInt").textContent = money(R.totalInterest);
  if (R.ltv > .80){
    $("moPmiNote").textContent = R.pmiEndMonth
      ? "PMI applies below 20% down. At this pace it ends around " + moWhen(R.pmiEndMonth) +
        " (federal law requires automatic removal at 22% equity either way)."
      : "PMI applies below 20% down. You can have it removed once you reach 20% equity, and federal law ends it automatically at 22%.";
  } else {
    $("moPmiNote").textContent = "No PMI; you're at or above 20% down.";
  }
  renderMortExtras(m, R);

  setBig("moTotal", money(R.total));
  setBig("moPI", money(R.pi));
  setBig("moEsc", money(R.total - R.pi));
  // name only what's actually in the figure
  const escParts = [[R.tax, "tax"], [R.ins, "insurance"], [R.pmi, "PMI"], [R.hoa, "HOA"],
    [R.maint, "upkeep"], [R.util, "utilities"]].filter(x => x[0] > 0).map(x => x[1]);
  const escTxt = escParts.length < 2 ? escParts.join("")
    : escParts.slice(0, -1).join(", ") + " and " + escParts[escParts.length - 1];
  $("moEscNote").textContent = escTxt ? escTxt.charAt(0).toUpperCase() + escTxt.slice(1) : "Nothing else added";

  const t = R.total || 1;
  $("moBars").innerHTML =
    bar("Principal & interest", R.pi, R.pi / t, "#4fbf95") +
    bar("Property tax", R.tax, R.tax / t, "#e9b872") +
    bar("Homeowners insurance", R.ins, R.ins / t, "#7d9fd6") +
    (R.pmi > 0 ? bar("Mortgage insurance (PMI)", R.pmi, R.pmi / t, "#e2795f") : "") +
    (R.hoa > 0 ? bar("HOA dues", R.hoa, R.hoa / t, "#8ba0ac") : "") +
    (R.maint > 0 ? bar("Maintenance", R.maint, R.maint / t, "#b48ec4") : "") +
    (R.util > 0 ? bar("Utilities", R.util, R.util / t, "#6fb0a6") : "");

  $("moTable").querySelector("tbody").innerHTML = R.years.map(y =>
    "<tr><td>" + y.year + "</td><td>" + money(y.interest) + "</td><td class='pos'>" +
    money(y.principal) + "</td><td>" + money(y.paid) + "</td><td>" +
    money(y.balance) + "</td></tr>").join("");

  // balance falling against cumulative interest and principal paid
  let ci = 0, cp = 0;
  const pts = [{year:0, base:R.loan, hi:0, lo:0}];
  R.years.forEach(y => { ci += y.interest; cp += y.principal;
    pts.push({year:y.year, base:y.balance, hi:cp, lo:ci}); });
  mortPoints = paintChart("chartMo", pts, R.years.length || 1, "band", [], 0, {enhanced:true});
  $("legendMo").innerHTML = swatch("#e9b872", "Balance remaining") +
    swatch("#4fbf95", "Principal paid") + swatch("#e2795f", "Interest paid");
}
attachChart("chartWrapMo", "chartMo", "tipMo", () => mortPoints,
  best => "<b>Year " + fmtNum(best.year) + "</b>" +
    "<br><span style='color:#e9b872'>Balance</span> <span class='n'>" + money(best.base) +
    "</span><br><span style='color:#4fbf95'>Principal paid</span> <span class='n'>" + money(best.hi) +
    "</span><br><span style='color:#e2795f'>Interest paid</span> <span class='n'>" + money(best.lo) + "</span>");

["moRate","moTax","moIns","moPmi","moHoa","moMaint","moUtil"].forEach(id =>
  $(id).addEventListener("input", renderMort));
$("moPrice").addEventListener("input", () => { syncDown("pct"); syncPmi(); renderMort(); });
$("moDownPct").addEventListener("input", () => { syncDown("pct"); syncPmi(); renderMort(); });
$("moDownAmt").addEventListener("input", () => { syncDown("amt"); syncPmi(); renderMort(); });
$("moTerm").addEventListener("change", renderMort);

["moExtraMo","moExtraOnce","moExtraWhen","moRefiRate","moRefiCost"].forEach(id =>
  $(id).addEventListener("input", renderMort));
["moRecast","moRefiTerm"].forEach(id => $(id).addEventListener("change", renderMort));
$("moExtrasOn").addEventListener("change", () => {
  $("moExtrasWrap").hidden = $("moExtrasOn").value !== "1";
  renderMort();
});

/* ---------- budget tool ---------- */
/* Grouped presets. freq is the default frequency for that row: 12 = a monthly
   figure, 1 = an annual figure. Rows carry their own amount and freq once the
   user edits them; travel and gifts default to annual since that's how people
   usually think of them. */
const BUDGET_PRESETS = [
  {group:"Housing", items:[
    {desc:"Rent / Mortgage", freq:12}, {desc:"Property tax", freq:12},
    {desc:"Utilities", freq:12}, {desc:"Internet & phone", freq:12},
    {desc:"Home / Renters insurance", freq:12}]},
  {group:"Transportation", items:[
    {desc:"Car payment", freq:12}, {desc:"Car insurance", freq:12},
    {desc:"Gas", freq:12}, {desc:"Maintenance & repairs", freq:1}]},
  {group:"Health", items:[
    {desc:"Health insurance", freq:12}, {desc:"Out-of-pocket medical", freq:1}]},
  {group:"Food", items:[
    {desc:"Groceries", freq:12}, {desc:"Eating out", freq:12}]},
  {group:"Lifestyle", items:[
    {desc:"Activities & hobbies", freq:12}, {desc:"Subscriptions", freq:12},
    {desc:"Travel", freq:1}, {desc:"Gifts", freq:1}]},
  {group:"Saving & debt", items:[
    {desc:"Savings & investments", freq:12}, {desc:"Other debt payments", freq:12}]}
];
function defaultBudget(){
  const rows = [];
  BUDGET_PRESETS.forEach(g => g.items.forEach(it =>
    rows.push({group:g.group, desc:it.desc, amount:0, freq:it.freq, custom:false})));
  return rows;
}
// Preset rows can never be added or removed, only ever renamed, so position i
// in the budget array always lines up with position i in this flattened list
// -- letting a blank rename fall back to "whatever this slot's default was"
// without having to store that default on every row.
const BUDGET_PRESET_DESCS = [];
BUDGET_PRESETS.forEach(g => g.items.forEach(it => BUDGET_PRESET_DESCS.push(it.desc)));
let budget = defaultBudget();

function annualize(r){ return r.amount * r.freq; }

/* Rebuilt only on structural change (add/remove/load); typing updates the model
   in place and recomputes totals, so focus is never lost. */
function buildBudget(){
  const groups = [];
  budget.forEach((r, i) => {
    let g = groups.find(x => x.name === r.group);
    if (!g){ g = {name:r.group, rows:[]}; groups.push(g); }
    g.rows.push({r, i});
  });
  $("bgList").innerHTML = groups.map(g =>
    "<div class='bggroup'><div class='bggroup-h'>" + (g.name || "Custom") + "</div>" +
    g.rows.map(({r, i}) => {
      const descCell = r.custom
        ? "<input class='desc' data-f='desc' data-i='" + i + "' value='" +
          String(r.desc).replace(/'/g, "&#39;") + "' placeholder='Description' aria-label='Item name'>"
        : isSavingsRow(r)
        ? "<span class='desc'>" + escapeHtml(r.desc) +
          "<span class='tipdot' data-tip='bgsavings' role='button' tabindex='0' aria-label='What is this?'>?</span></span>"
        : "<span class='desc' contenteditable='true' spellcheck='false' data-name='" + i +
          "' title='Click to rename' aria-label='Item name'>" + escapeHtml(r.desc) + "</span>";
      const del = r.custom
        ? "<button class='del' type='button' data-del='" + i + "' title='Remove' aria-label='Remove'>\u00d7</button>"
        : "<span class='delspace'></span>";
      return "<div class='bgrow'>" + descCell +
        "<div class='inputwrap'><span class='affix'>$</span><input type='text' inputmode='decimal' " +
          "data-money data-nonneg data-f='amount' data-i='" + i + "' value='" +
          groupDigits(r.amount, true) + "' aria-label='" + escapeHtml(r.desc) + " amount'></div>" +
        "<span class='seg bgseg' data-f='freqseg' data-i='" + i + "'>" +
          "<button type='button' data-fv='12'" + (r.freq === 12 ? " class='on'" : "") + ">/mo</button>" +
          "<button type='button' data-fv='1'" + (r.freq === 1 ? " class='on'" : "") + ">/yr</button>" +
        "</span>" + del + "</div>";
    }).join("") + "</div>").join("");
  initFields($("bgList"));
}

/* "Savings & investments" and the "Retirement contribution" and "College
   savings" lines (added via the handoff buttons) are money being set aside,
   not spent \u2014 they're kept out of total spending and the emergency fund,
   and shown as saving instead. */
const SAVINGS_DESCS = ["Savings & investments", "Retirement contribution", "College savings"];
function isSavingsRow(r){ return SAVINGS_DESCS.includes(r.desc); }

function renderBudget(){
  const incFreq = bgIncomeFreq;
  const incomeYr = num("bgIncomeIn") * incFreq;
  const spentYr = budget.reduce((a, r) => a + (isSavingsRow(r) ? 0 : annualize(r)), 0);
  const savedYr = budget.reduce((a, r) => a + (isSavingsRow(r) ? annualize(r) : 0), 0);
  const leftYr = incomeYr - spentYr - savedYr;
  const pct = incomeYr > 0 ? leftYr / incomeYr : 0;

  setBig("bgIncome", money(incomeYr));
  setBig("bgSpent", money(spentYr));
  setBig("bgLeft", money(leftYr));
  $("bgLeft").className = "v " + (leftYr < 0 ? "neg" : "pos");
  $("bgLeftNote").textContent = incomeYr > 0
    ? (leftYr < 0 ? "Over budget by " : "") + pctStr(Math.abs(pct), 1) +
      (leftYr < 0 ? " of income" : " of income left")
    : "Enter your income to begin";

  $("bgTotYr").textContent = money(spentYr);
  $("bgTotMo").textContent = money(spentYr / 12);
  $("bgSaveRow").hidden = !(savedYr > 0);
  if (savedYr > 0) $("bgSaveMo").textContent = money(savedYr / 12);
  const ly = $("bgLeftYr"), lm = $("bgLeftMo");
  ly.textContent = money(leftYr); lm.textContent = money(leftYr / 12);
  ly.className = "v " + (leftYr < 0 ? "neg" : "pos");
  lm.className = "v " + (leftYr < 0 ? "neg" : "pos");

  renderEF(spentYr / 12);
}

$("bgList").addEventListener("input", e => {
  const el = e.target, f = el.getAttribute && el.getAttribute("data-f");
  if (!f || f === "freq") return;
  const i = parseInt(el.getAttribute("data-i"), 10);
  if (!budget[i]) return;
  if (f === "amount") budget[i].amount = num2(el.value);
  else if (f === "desc") budget[i].desc = el.value;
  renderBudget();
});
/* Preset item names double as a rename field, the same way stage names work:
   selecting all text on focus means a click can just be typed over, Enter
   commits instead of adding a line break, and the value only actually saves
   on blur. A blank entry falls back to that slot's original default name
   rather than staying empty. The one preset row that's excluded from the
   spending total ("Savings & investments") is left out of this entirely --
   see the isSavingsRow() branch in buildBudget(), which renders it as plain
   text with an explanatory tooltip instead of a rename field. */
$("bgList").addEventListener("focusin", e => {
  const el = e.target;
  if (!el.getAttribute || el.getAttribute("data-name") === null) return;
  const range = document.createRange();
  range.selectNodeContents(el);
  const sel = window.getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
});
$("bgList").addEventListener("keydown", e => {
  const el = e.target;
  if (el.getAttribute && el.getAttribute("data-name") !== null && e.key === "Enter"){
    e.preventDefault();
    el.blur();
  }
});
$("bgList").addEventListener("focusout", e => {
  const el = e.target;
  const attr = el.getAttribute && el.getAttribute("data-name");
  if (attr === null || attr === undefined) return;
  const i = parseInt(attr, 10);
  if (!budget[i]) return;
  const raw = el.textContent.replace(/\s+/g, " ").trim().slice(0, 60);
  budget[i].desc = raw || BUDGET_PRESET_DESCS[i] || budget[i].desc;
  buildBudget(); renderBudget();
});
$("bgList").addEventListener("click", e => {
  const b = e.target.closest ? e.target.closest("button[data-fv]") : null;
  if (!b) return;
  const seg = b.parentNode;
  const i = parseInt(seg.getAttribute("data-i"), 10);
  if (!budget[i]) return;
  budget[i].freq = parseInt(b.getAttribute("data-fv"), 10);
  seg.querySelectorAll("button").forEach(x =>
    x.classList.toggle("on", x.getAttribute("data-fv") === String(budget[i].freq)));
  renderBudget();
});
$("bgList").addEventListener("click", e => {
  const b = e.target.closest ? e.target.closest("button[data-del]") : null;
  if (!b) return;
  budget.splice(parseInt(b.getAttribute("data-del"), 10), 1);
  buildBudget(); renderBudget();
});
$("bgAdd").addEventListener("click", () => {
  budget.push({group:"Custom", desc:"", amount:0, freq:12, custom:true});
  buildBudget(); renderBudget();
  // focus the new description field
  const inputs = $("bgList").querySelectorAll("input.desc");
  if (inputs.length) inputs[inputs.length - 1].focus();
});

/* Shared handoff target for other tools sending a line into the budget.
   Updates an existing row with the same description instead of duplicating
   it if the button is clicked more than once. */
function upsertBudgetLine(desc, monthlyAmount){
  const existing = budget.find(r => r.desc === desc);
  if (existing){
    existing.amount = monthlyAmount;
    existing.freq = 12;
  } else {
    budget.push({group:"Custom", desc, amount:monthlyAmount, freq:12, custom:true});
  }
  buildBudget(); renderBudget();
}

/* Reads whatever is currently entered in each retirement mode, regardless of
   which tab happens to be open \u2014 the inputs hold their values in the
   background even while you're looking at Budget. Basic is checked first
   since it's the default landing mode; Stages uses its first stage, since
   that's the contribution happening right now. */
/* Same pattern as the Drawdown tool's "copy portfolio" chooser: every source
   that actually has a contribution is offered, with its monthly-equivalent
   dollar amount shown right there, rather than silently picking the first
   one that happens to be nonzero and leaving the person to guess from the
   toast message afterward. */
$("bgCopyRetire").addEventListener("click", async () => {
  const sources = [
    {contrib: num("qContrib"), period: $("qPeriod").value, label: "Basic"},
    {contrib: num("contrib"), period: $("period").value, label: "Advanced"},
    {contrib: stages.length ? stages[0].contrib : 0,
     period: stages.length ? stages[0].period : "Monthly", label: "Stages"}
  ].map(c => ({label: c.label, value: c.contrib * PPY[c.period] / 12}))
   .filter(c => c.value > 0);

  if (!sources.length){
    toast("Set a contribution amount in Basic, Advanced, or Stages first");
    return;
  }
  if (sources.length === 1){
    applyBudgetRetireCopy(sources[0]);
    return;
  }

  const choice = await showPopup("Copy from which plan?", sources.map(s =>
    ({label: s.label, desc: money(s.value) + "/mo", money: true})));
  if (choice >= 0) applyBudgetRetireCopy(sources[choice]);
});
function applyBudgetRetireCopy(source){
  const monthly = Math.round(source.value);
  upsertBudgetLine("Retirement contribution", monthly);
  toast("Added " + money(monthly) + "/mo from " + source.label);
}

$("bgCopyCollege").addEventListener("click", () => {
  const inp = readCollege();
  if (!inp.kids.some(k => k.annualCost > 0)){ toast("Set up the College Savings tool first"); return; }
  const mo = collegeMonthly(inp);
  if (!(mo > 0)){ toast("No monthly amount needed there yet"); return; }
  const monthly = Math.round(mo);
  upsertBudgetLine("College savings", monthly);
  toast("Added " + money(monthly) + "/mo from College Savings");
});

$("rbCopyMort").addEventListener("click", () => {
  const price = num("moPrice");
  if (!(price > 0)){ toast("Set up the Mortgage tool first"); return; }
  $("rbPrice").value = groupDigits(price, true);
  $("rbDown").value = $("moDownPct").value;
  $("rbRate").value = $("moRate").value;
  // rbTerm only offers 30/20/15; a 10-year mortgage falls back to 15, the
  // closest option, rather than silently leaving the old term selected.
  const morTerm = $("moTerm").value;
  $("rbTerm").value = ["30", "20", "15"].includes(morTerm) ? morTerm : "15";
  $("rbPropTax").value = $("moTax").value;
  $("rbIns").value = $("moIns").value;
  $("rbMaint").value = $("moMaint").value;
  renderRentBuy();
  toast("Copied the home from your mortgage calculation");
});
["bgIncomeIn"].forEach(id => $(id).addEventListener("input", renderBudget));
let bgIncomeFreq = 1;   // 1 = typed as annual, 12 = typed as monthly
$("bgIncomeFreq").addEventListener("click", e => {
  const b = e.target.closest ? e.target.closest("button[data-freq]") : null;
  if (!b) return;
  bgIncomeFreq = parseInt(b.getAttribute("data-freq"), 10);
  $("bgIncomeFreq").querySelectorAll("button").forEach(x =>
    x.classList.toggle("on", x.getAttribute("data-freq") === String(bgIncomeFreq)));
  renderBudget();
});

function renderEF(monthlySpend) {
  var mo = Math.max(1, Math.round(num("efMonths")) || 6);
  $("efLabel").textContent = mo + "-month emergency fund";
  $("efTarget").textContent = money(monthlySpend * mo);
}
$("efMonths").addEventListener("input", renderBudget);

/* The budget isn't a <table>, so the automatic CSV buttons skip it. This
   exports the same figures as a three-column sheet: item, amount, and whether
   it's a monthly or yearly figure. Custom items (added at the end) are part of
   the same list, so they're included too. Rows left blank or at zero are left
   out. It's a flat list of the populated items -- no category headings --
   with income and the totals as labeled rows. */
function exportBudgetCSV(){
  const period = f => f === 12 ? "Per month" : "Per year";
  const incomeAmt = num("bgIncomeIn");
  const spentYr = budget.reduce((a, r) => a + (isSavingsRow(r) ? 0 : annualize(r)), 0);
  const savedYr = budget.reduce((a, r) => a + (isSavingsRow(r) ? annualize(r) : 0), 0);
  if (!(incomeAmt > 0) && !(spentYr > 0) && !(savedYr > 0)){
    toast("Nothing to export yet"); return;
  }
  const rows = [["Budget Item", "Amount", "Period"]];
  if (incomeAmt > 0) rows.push(["Income after taxes", money(incomeAmt), period(bgIncomeFreq)]);
  budget.forEach(r => {
    if (!(r.amount > 0)) return;   // skip blank / zero rows
    rows.push([r.desc, money(r.amount), period(r.freq)]);
  });
  const leftYr = incomeAmt * bgIncomeFreq - spentYr - savedYr;
  rows.push(["Total spending", money(spentYr), "Per year"]);
  if (savedYr > 0) rows.push(["Total saving", money(savedYr), "Per year"]);
  rows.push(["Left over", money(leftYr), "Per year"]);

  const csv = rows.map(cols => cols.map(c => csvEscape(String(c))).join(",")).join("\r\n");
  const blob = new Blob([csvFile(csv)], {type:"text/csv;charset=utf-8"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "retcalc-budget.csv";
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  toast("Saved " + a.download);
}
$("bgCsv").addEventListener("click", exportBudgetCSV);
/* ---------- college UI ---------- */
var collegePoints = [], clMulti = false;

/* The children being saved for. The first child's fields keep the ids the
   tool had when it planned for one (clPreset, clCost, clYears,
   clCollegeYrs); the rest are drawn after it. */
const CL_PRESETS = [["27000", "Public in-state · ~$27,000/yr"],
  ["59000", "Private non-profit · ~$59,000/yr"], ["82000", "Elite / Ivy · ~$82,000/yr"],
  ["0", "Custom"]];
let clKids = [{preset:"27000", cost:27000, years:18, collegeYrs:4}];

function buildCollegeKids(){
  const many = clKids.length > 1;
  $("clKids").innerHTML = clKids.map((k, i) => {
    const id = f => i ? "" : " id='" + f + "'", lab = f => i ? "" : " for='" + f + "'";
    const fields =
      "<div class='field'><label" + lab("clPreset") + ">School type" + (i ? "" :
        "<span class='tipdot' data-tip='schooltype' role='button' tabindex='0' aria-label='What is this?'>?</span>") + "</label>" +
        "<select" + id("clPreset") + " data-f='preset' data-i='" + i + "' aria-label='Child " + (i + 1) + " school type'>" +
        CL_PRESETS.map(o => "<option value='" + o[0] + "'" + (o[0] === String(k.preset) ? " selected" : "") + ">" + o[1] + "</option>").join("") +
        "</select></div>" +
      "<div class='field'><label" + lab("clCost") + ">Annual cost today</label>" +
        "<div class='inputwrap'><span class='affix'>$</span><input" + id("clCost") + " type='text' inputmode='decimal' data-money data-nonneg" +
        " data-f='cost' data-i='" + i + "' value='" + groupDigits(k.cost, true) + "' aria-label='Child " + (i + 1) + " annual cost today'></div></div>" +
      "<div class='two'>" +
        "<div class='field'><label" + lab("clYears") + ">Years until college</label>" +
          "<div class='inputwrap'><input" + id("clYears") + " type='text' inputmode='decimal' data-num data-step='1' min='0' max='25' data-nonneg" +
          " data-f='years' data-i='" + i + "' value='" + k.years + "' aria-label='Child " + (i + 1) + " years until college'><span class='affix'>yrs</span></div></div>" +
        "<div class='field'><label" + lab("clCollegeYrs") + ">Years of college</label>" +
          "<div class='inputwrap'><input" + id("clCollegeYrs") + " type='text' inputmode='decimal' data-num data-step='1' min='1' max='8' data-nonneg" +
          " data-f='collegeYrs' data-i='" + i + "' value='" + k.collegeYrs + "' aria-label='Child " + (i + 1) + " years of college'><span class='affix'>yrs</span></div></div>" +
      "</div>";
    return many
      ? "<div class='stagecard clkid'><div class='stagehead'><span class='clkid-name'>Child " + (i + 1) + "</span>" +
          "<button class='btn mini' type='button' data-del='" + i + "'>Remove</button></div>" + fields + "</div>"
      : fields;
  }).join("");
  $("clAddKid").textContent = many ? "Add another child" : "Add a child";
  $("clSavedLbl").firstChild.textContent = many ? "Currently saved, for all of them" : "Currently saved";
  initFields($("clKids"));
}

function readCollege() {
  const kids = clKids.map(k => ({
    yearsUntil: Math.min(25, +k.years || 0),
    annualCost: +k.cost || 0,
    collegeYrs: Math.max(1, Math.round(+k.collegeYrs || 0))
  }));
  return {
    yearsUntil:  kids[0].yearsUntil,
    annualCost:  kids[0].annualCost,
    tuitionInfl: rate("clInfl"),
    investRet:   rate("clReturn"),
    saved:       num("clSaved"),
    collegeYrs:  kids[0].collegeYrs,
    kids:        kids
  };
}
/* The monthly amount to save now, for however many children: what the
   budget, guide and tool help carry. */
function collegeMonthly(inp){
  if (inp.kids && inp.kids.length > 1){ const P = collegePlanCalc(inp); return P ? P.monthly : 0; }
  return inp.annualCost > 0 && inp.yearsUntil > 0 ? collegeSavingsCalc(inp).monthly : 0;
}

function renderCollege() {
  var inp = readCollege();
  clMulti = inp.kids.length > 1;
  $("clEachPanel").hidden = !clMulti;
  $("clShortK").textContent = clMulti ? "Needed today" : "Needed when college starts";
  $("clShortTip").setAttribute("data-tip", clMulti ? "collegepvall" : "collegepv");
  $("clSavGrowK").textContent = clMulti ? "What you've saved covers" : "What you've saved grows to";
  $("clTable").querySelector("thead").innerHTML = "<tr><th>Year</th><th>Balance</th><th>You added</th><th>Growth</th><th>" +
    (clMulti ? "Paid for college" : "Projected cost") + "</th></tr>";
  if (clMulti) return renderCollegeFamily(inp);
  if (inp.annualCost <= 0 || inp.yearsUntil <= 0) {
    setBig("clMonthly", "—");
    setBig("clTotalOut", "—");
    setBig("clShortOut", "—");
    return;
  }
  var R = collegeSavingsCalc(inp);

  $("clSavGrow").textContent = money(R.savingsAtStart);

  setBig("clMonthly", money(R.monthly, 0));
  $("clMonthlyNote").textContent = "for " + fmtNum(inp.yearsUntil) + " years at " + pctStr(inp.investRet, 1);
  setBig("clTotalOut", money(R.totalFuture));
  $("clTotalNote").textContent = inp.collegeYrs + " years at " + money(inp.annualCost, 0) + "/yr, " + pctStr(inp.tuitionInfl, 1) + " inflation";
  setBig("clShortOut", money(R.shortfall));
  $("clShortNote").textContent = "Less than the " + money(R.totalFuture) +
    " total, since what's saved keeps earning " + pctStr(inp.investRet, 1) +
    " while later years' tuition is paid";

  // The comparison line is what the full 4-year cost would be if college
  // started in that year — rising with tuition inflation, landing on the
  // real total by the time college actually starts. Year 0 uses the same
  // formula rather than defaulting to zero, so the line starts at a real cost.
  function costIfStartingAt(t){
    var total = 0;
    for (var k = 0; k < inp.collegeYrs; k++){
      total += inp.annualCost * Math.pow(1 + inp.tuitionInfl, t + k);
    }
    return total;
  }
  var pts = [{year:0, base:inp.saved, hi:costIfStartingAt(0), lo:0}];
  R.rows.forEach(function(r) {
    pts.push({year: r.year, base: r.balance, hi: costIfStartingAt(r.year), lo: 0});
  });
  collegePoints = paintChart("chartCl", pts, inp.yearsUntil, "band", [], 0, {enhanced:true, noLoLine:true});
  $("legendCl").innerHTML =
    swatch("#e9b872", "Your savings") +
    swatch("#4fbf95", "Cost of college, that year");

  $("clTable").querySelector("tbody").innerHTML = R.rows.map(function(r) {
    return "<tr><td>" + fmtNum(r.year) + "</td><td>" + money(r.balance) +
      "</td><td class='pos'>" + money(r.contribs) + "</td><td class='pos'>" +
      money(r.growth) + "</td><td>" + money(r.projCost) + "</td></tr>";
  }).join("");
}

/* How the monthly amount runs: one figure, or one that steps down once an
   older child's college has started. */
function collegePhaseNote(P){
  const yrs = m => fmtNum(Math.round(m / 12 * 10) / 10);
  const ph = P.phases, first = ph[0];
  let s = "for " + yrs(first.to) + " years";
  ph.slice(1).forEach(x => {
    s += x.monthly > 0 ? ", then " + money(x.monthly, 0) + "/mo for " + yrs(x.to - x.from) + " more" : ", then nothing more";
  });
  return s;
}
function renderCollegeFamily(inp){
  const P = collegePlanCalc(inp);
  if (!P){
    ["clMonthly", "clTotalOut", "clShortOut"].forEach(id => setBig(id, "—"));
    ["clMonthlyNote", "clTotalNote", "clShortNote", "clSavGrow"].forEach(id => { $(id).textContent = ""; });
    $("clEach").innerHTML = ""; $("clTable").querySelector("tbody").innerHTML = "";
    collegePoints = paintChart("chartCl", [], 0, "band", [], 0, {});
    return;
  }
  const n = P.kids.length;
  $("clSavGrow").textContent = P.pvToday > 0 ? pctStr(Math.min(1, inp.saved / P.pvToday), 0) + " of it" : "—";
  setBig("clMonthly", money(P.monthly, 0));
  $("clMonthlyNote").textContent = (n === 2 ? "for both children, " : "for all " + n + " children, ") + collegePhaseNote(P);
  setBig("clTotalOut", money(P.totalFuture));
  $("clTotalNote").textContent = fmtNum(P.kids.reduce((a, k) => a + k.yearCosts.length, 0)) +
    " years of college in all, at " + pctStr(inp.tuitionInfl, 1) + " tuition inflation";
  setBig("clShortOut", money(P.pvToday));
  $("clShortNote").textContent = "A lump sum today that, earning " + pctStr(inp.investRet, 1) +
    ", would pay every bill as it comes";

  $("clEach").innerHTML = P.kids.map(k =>
    "<div class='kv'><span class='k'>Child " + (k.index + 1) + ": " + fmtNum(k.yearCosts.length) + " years, starting in " +
      fmtNum(k.yearsUntil) + (k.yearsUntil === 1 ? " year" : " years") + "</span><span class='v'>" + money(k.total) +
    "</span></div>").join("") +
    (P.skipped ? "<div class='kv'><span class='k'>Left out</span><span class='v'>" + P.skipped +
      (P.skipped === 1 ? " child" : " children") + " with no cost or no years until college</span></div>" : "");

  const pts = [{year:0, base:inp.saved, hi:P.pvToday, lo:0}];
  P.rows.forEach(r => pts.push({year:r.year, base:r.balance, hi:r.needed, lo:0}));
  collegePoints = paintChart("chartCl", pts, P.rows.length, "band", [], 0, {enhanced:true, noLoLine:true});
  $("legendCl").innerHTML =
    swatch("#e9b872", "Your savings") +
    swatch("#4fbf95", "Needed then for the bills still ahead");

  $("clTable").querySelector("tbody").innerHTML = P.rows.map(r =>
    "<tr><td>" + fmtNum(r.year) + "</td><td>" + money(r.balance) +
      "</td><td class='pos'>" + money(r.contribs) + "</td><td class='pos'>" +
      money(r.growth) + "</td><td>" + (r.paid > 0 ? money(r.paid) : "—") + "</td></tr>").join("");
}

