  const P = TH_TOURS[th.tool].pages;
  th.page = Math.max(0, Math.min(P.length - 1, th.page + parseInt(b.getAttribute("data-tp"), 10)));
  thFill();
  $("thCoachBody").scrollTop = 0;
  const f = document.querySelector(P[th.page].focus);
  if (f) thScrollTo(f);
